INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.fr-registry-search','Search French companies by name or SIREN (top 10)','French company search and company lookup by name or SIREN in the official French company registry (INSEE Sirene / INPI RNE open data). Name search returns the top 10 matches with identity, SIREN, NAF code, city and active/ceased status, plus a score_confiance (0-1 match confidence) that helps disambiguate homonyms. The entry point to official data and company data on France: resolve a trading name to its SIREN identifier before pulling the full company profile, filings or financials. Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type": "object", "properties": {"q": {"type": "string", "description": "Company name, or a French identifier (SIREN, SIRET, VAT) — spaced or labelled (\"SIREN : 552 032 534\") resolves directly. Unsupported characters are stripped, not rejected; 400 only if nothing searchable is left (1-100 chars once cleaned).", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.registry-profile','Full company profile by SIREN','Full French company profile by SIREN: official company data from the French company registry (INSEE Sirene / INPI RNE). One company lookup returns legal name, legal form, head-office address, NAF code, workforce bracket, creation date, active or ceased status, officers with name and role, collective agreement and the computed intra-EU VAT number. The core KYB building block for verifying a French counterparty: registry facts for due diligence, compliance and onboarding checks. Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}, "geo": {"type": "boolean", "description": "true = include GPS coordinates (WGS84) of establishments", "x-parameter-location": "query"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.fr-financials','Annual financial data from filed accounts (INPI / Banque de France ratios)','Annual financial data from filed accounts (INPI / Banque de France ratios) Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.fr-kyb','Complete KYB file for a French company (one call)','Complete KYB file for a French company (one call) Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.eu-registry-search','Search European companies across official registers (unified schema)','Search European companies across official registers (unified schema) Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type": "object", "properties": {"q": {"type": "string", "description": "Company name — 2 to 100 characters once unsupported characters are stripped.", "x-parameter-location": "query"}, "pays": {"type": "string", "pattern": "^[A-Za-z]{2}$", "description": "Optional ISO-3166 alpha-2 country filter", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.registry-profile','Unified European company profile','Unified European company profile Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type": "object", "properties": {"pays": {"type": "string", "pattern": "^[A-Za-z]{2}$", "description": "ISO-3166 alpha-2 country code (NO, EE, LV, BE, CH, CZ, SK, FI, PL; DK/GB when enabled)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^[A-Za-z0-9.-]{1,20}$", "description": "National register identifier", "x-parameter-location": "path"}}, "required": ["pays", "id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-etablissements','List establishments (SIRET) of a company','All establishments (SIRET) of a French company: the complete list of business locations registered under one SIREN, official data from the French company registry (INSEE Sirene), head office and branches alike, each with its address and open or closed status. Use it to map the branches and addresses of a company across France, or to check whether a given SIRET is still open. The SIREN identifies the legal entity; the SIRET identifies each of its establishments. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-alertes','Legal alerts from BODACC (insolvency, deregistration, business sales)','Announcements grouped by family (procedures collectives, radiations, ventes/cessions), most recent first, with judgment details. Each announcement carries `role`: `sujet` (this company is the debtor), `partie_citee` or `indetermine`. Since 2026-09-04, insolvency notices of ANOTHER company that merely cite this one as a party (creditor bank, counterparty) are served apart in `mentions_comme_partie` with the real debtor''s name (`sujet_annonce`), and count towards NO verdict — a creditor listed in a debtor''s conciliation judgment used to be scored as if it were in proceedings itself. `denomination` is the Sirene legal name (`denomination_source`), never the trade label of the latest notice. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-contentieux','Commercial-court decisions linked to the company (Judilibre open data)','Commercial-court decisions linked to the SIREN, most recent first (100 max, `tronque` beyond): court and code, date, docket number, closed-list `nature` and `role`, the other legal entities involved (SIREN + Sirene name), `redondante_bodacc` for insolvency judgments already served by /alertes, and the official Judilibre URL. Plus counts, the measured coverage (61.8% of decisions carry a usable identifier) and the source update date. Never a text, a natural person''s name or an amount. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-marches-publics','Public procurement contracts won (official DECP data)','Aggregates (count and total amount as TWO bounds — raw per published row, and deduplicated per (buyer, date, amount, CPV) key —, contracts still running, next expiry) plus the 100 most recent contracts with buyer identity resolved, estimated end dates and a per-row publication status (unique, multi-platform, repeated, per-establishment, amendment) with linked rows. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-marches-expirations','Tender anticipation: French public contracts expiring within a window','Contracts whose ESTIMATED end date (notification + initially declared duration; duration amendments are absent from the DECP source) falls inside the window, sorted by end date: buyer (SIRET + resolved name), incumbent holders, amount (after amendment when published), framework-agreement flag, CPV, department. Buyers typically re-tender 4-9 months before expiry. An empty list is scoped honestly: contracts under EUR 40k excl. VAT are unpublished. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"cpv": {"type": "string", "pattern": "^\\d{2,8}$", "maxLength": 500, "minLength": 1, "description": "CPV prefix (45 = construction works)", "x-parameter-location": "query"}, "departement": {"type": "string", "pattern": "^(?:0[1-9]|1\\d|2[1-9]|[3-8]\\d|9[0-5]|2[AB]|97[1-8]|98[4-8])$", "maxLength": 500, "minLength": 1, "description": "French department code (01-95, 2A, 2B, 971-978, 984-988)", "x-parameter-location": "query"}, "fenetre_mois": {"type": "integer", "minimum": 1, "maximum": 24, "description": "Window in months (default 12)", "x-parameter-location": "query"}, "page": {"type": "integer", "minimum": 1, "maximum": 500, "description": "50 contracts per page", "x-parameter-location": "query"}}, "required": []}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-acheteur-siret-profil','Procurement profile of a French public buyer','Contract counts and amounts, activity by year (5y), top CPV segments, incumbent suppliers with contracts expiring within 18 months, framework-agreement share, average bids received per tender and median data-publication delay. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siret": {"type": "string", "pattern": "^\\d{14}$", "maxLength": 500, "minLength": 1, "description": "14-digit SIRET of the buyer (Luhn-checked)", "x-parameter-location": "path"}}, "required": ["siret"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-concurrents-marches','Rival contractors on the same CPV segments (public procurement)','The company''s top-5 CPV segments (last 5 years) and the top-15 rival contractors on those segments over the last 3 years, with contract counts, total amounts and shared segments. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-es-hoja-actes','Spanish company acts from the BORME gazette (Registro Mercantil, section A), by hoja registral','ES: Spanish company acts from the official BORME gazette (Registro Mercantil, section A) by hoja registral — the register key, e.g. VI-23141: incorporations, officer appointments and dismissals (role + name), capital changes, mergers, dissolutions, insolvency. Daily filings flow since 2009, newest first (100 max + total count). Spanish personal IDs (DNI/NIE) and natural-person sole-shareholder names are redacted at ingestion. Basado en datos de la Agencia Estatal Boletin Oficial del Estado (boe.es). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"hoja": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9 .-]{1,24}$", "maxLength": 500, "minLength": 1, "description": "Hoja registral (register-sheet key, e.g. VI-23141) — get it from /v1/eu/recherche?pays=ES. The BORME does not publish the NIF; the hoja is the native key.", "x-parameter-location": "path"}}, "required": ["hoja"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-no-id-comptes','Norwegian annual accounts (Regnskapsregisteret) — latest year live + every year accumulated since 2026-07','NO: Norwegian company annual accounts and financial statements from Norway''s official Regnskapsregisteret (Brønnøysundregistrene, Brreg, NLOD 2.0). Query: /v1/eu/entreprise/NO/923609016/comptes (9-digit organisasjonsnummer). Latest filed fiscal year live from the register plus earlier years collected since 2026-07 — financials: balance sheet (assets, equity, debts), P&L (operating income and result, net result) in the filing currency (can be USD). Banks and insurers are not served by the source. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"id": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit Norwegian organisasjonsnummer (no spaces)", "x-parameter-location": "path"}}, "required": ["id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-no-id-evenements','Norwegian legal events (Enhetsregisteret) — bankruptcy, winding-up, strike-off','NO: Norwegian company legal events from the official Enhetsregisteret (Brreg, NLOD 2.0) for insolvency and credit risk monitoring: bankruptcy (konkurs, with the registered date), voluntary or compulsory liquidation, and strike-off, plus current flags checked live. 9-digit organisasjonsnummer. A live-verified company with no flag gets an explicit positive answer. Coarser than France''s BODACC: no ruling text, no court; undated events carry an upper-bound date. Legal persons only, never individuals. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"id": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit Norwegian organisasjonsnummer (no spaces)", "x-parameter-location": "path"}}, "required": ["id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-gb-company-number-dirigeants','UK company officers (Companies House, live) — active directors and secretaries','GB: UK company officers live from Companies House, the official UK company registry, by company number (e.g. GB/00102498): active directors and secretaries with role, appointment date, nationality, occupation, country of residence and month+year of birth only — never a correspondence address (GDPR minimisation). Resigned-officer count included. Built for KYB and due diligence on director appointments and governance. Contains public sector information licensed under the Open Government Licence v3.0. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number (8 characters incl. leading zeros, e.g. 00102498, SC123456, NI017460)", "x-parameter-location": "path"}}, "required": ["company_number"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-gb-company-number-beneficiaires-effectifs','UK beneficial owners (PSC register, Companies House, live)','GB: UK beneficial owners (PSC, persons with significant control) live from Companies House for AML, KYB and compliance: individual and corporate-entity PSCs with natures of control (ownership/voting bands), notification dates, plus official PSC statements. Ceased PSCs excluded by default (inclure_cesses=true adds them with their ceased date). Beyond French-registry parity — France exposes no open UBO register. Month+year of birth only, no addresses. Open Government Licence v3.0 (Companies House). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number", "x-parameter-location": "path"}, "inclure_cesses": {"type": "string", "enum": ["true"], "maxLength": 500, "minLength": 1, "description": "Also return ceased PSCs (with their ceased_on date)", "x-parameter-location": "query"}}, "required": ["company_number"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-gb-company-number-insolvabilite','UK company insolvency record (Companies House, live)','GB: UK company insolvency record for credit risk and compliance screening, live from Companies House by company number: liquidation (compulsory or voluntary), administration, receivership and other cases with their dates and insolvency practitioners (name and role only, no addresses). A company with NO recorded case returns an explicit positive answer (200, aucune_procedure) — the register is authoritative, an empty record is a fact. Open Government Licence v3.0 (Companies House). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number", "x-parameter-location": "path"}}, "required": ["company_number"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-lv-regnr-comptes','Latvian annual accounts (Uzņēmumu reģistrs / VID filings) — every filed fiscal year in one call','LV: Latvian company annual accounts — official financial statements from VID filings via the Uzņēmumu reģistrs open data of Latvia (CC0, daily). Query: /v1/eu/entreprise/LV/40003032065/comptes (11-digit registration number). EVERY filed fiscal year in one call: balance sheet, profit and loss (revenue, net income), cash flow when filed, employees, as published (EUR, LVL before 2014; statutory and consolidated filings kept apart). Null = not published, never zero. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-lv-regnr-insolvabilite','Latvian company insolvency record (Uzņēmumu reģistrs, daily national photo)','LV: Latvian company insolvency record from the official Uzņēmumu reģistrs open data (CC0, daily photo since 2008), built for credit risk and compliance screening: insolvency and legal protection proceedings in Latvia with start/end dates, resolution, court and case number. A registered company with NO proceeding returns an explicit positive answer (200, aucune_procedure: true) — the register is authoritative. 11-digit registration number. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-lv-regnr-dirigeants','Latvian company officers (Uzņēmumu reģistrs, refreshed daily)','LV: Latvian company officers and directors from the official Uzņēmumu reģistrs (Latvia''s company registry) open data (CC0, daily): board members, chairs, liquidators and other representatives with name, role, governing body, representation rights (individually/jointly) and registration date; corporate officers carry their own registration number. For KYB and governance. GDPR minimisation: never the Latvian personal identity number, birth month+year only when published. 11-digit registration number. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-lv-regnr-beneficiaires-effectifs','Latvian beneficial owners (patiesie labuma guvēji, open national UBO register)','LV: Latvian beneficial owners (patiesie labuma guvēji) from the official Uzņēmumu reģistrs open data (CC0, refreshed daily), for AML, KYB and compliance ownership checks: registered UBOs in Latvia with name, nationality, country of residence and registration date — an open national UBO register, depth France does not expose. GDPR minimisation: never the Latvian personal identity number, birth month+year only when published. 11-digit registration number. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-lv-regnr-evenements','Latvian company legal events (Uzņēmumu reģistrs — liquidations, reorganisations, VID suspensions, securing measures)','LV: Latvian company legal events from the official Uzņēmumu reģistrs open data (CC0, daily photo): liquidations and activity terminations (incl. by court or tax authority), mergers, acquisitions, divisions and transformations with the other company''s number, VID activity suspensions, securing measures (prohibitions, liens, attachments) with the registering institution. Closed-list types plus source code and wording. A registered company with no event gets aucun_evenement: true. 11-digit number. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-lv-regnr-associes','Latvian company members and shareholders (Uzņēmumu reģistrs — corporate holders named, natural persons counted)','LV: Latvian company members and shareholders from the official Uzņēmumu reģistrs open data (CC0, daily): SIA members (parts) and AS registered shareholders with number of shares, nominal value and currency as published (LVL before 2014), votes, share of nominal capital and holding start date. Corporate holders are named with their registration number; natural persons are COUNTED, never named (GDPR); dematerialised shares show the depository only. Group links for KYB. 11-digit number. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-ee-registrikood-comptes','Estonian annual-report key figures (e-Business Register open data) — every published year in one call','EE: Estonian company annual accounts — key figures from the official e-Business Register open data (RIK, CC BY 4.0, refreshed monthly). Query: /v1/eu/entreprise/EE/10003666/comptes (8-digit registrikood). EVERY published financial year since 2019 in one call: balance sheet (assets, equity, liabilities), revenue, employee expense, depreciation, operating and net profit, average FTE headcount — in EUR as published. Statutory and consolidated figures kept apart. Null = not published, never zero. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"registrikood": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Estonian registry code", "x-parameter-location": "path"}}, "required": ["registrikood"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-ee-registrikood-evenements','Estonian registry rulings (määrused) — striking-off and dissolution warnings, fines, entries','EE: Estonian registry rulings (määrused) — early-warning credit-risk signal from the e-Business Register open data (RIK, CC BY 4.0, daily national photo): entries, remedy orders, striking-off/dissolution WARNINGS, annual-report fines, dated. alerte flags a CLOSED type list (rest in types_non_qualifies); nombre_alertes excludes only rulings explicitly resolved (etat_code=L) — every other state (J, K, unseen codes) still counts. A still-registered entity with no ruling gets a dated positive answer. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"registrikood": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Estonian registry code", "x-parameter-location": "path"}}, "required": ["registrikood"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-se-orgnr-comptes','Swedish annual accounts (Bolagsverket iXBRL filings) — every digitally filed fiscal year in one call','SE: Swedish company annual accounts and financial statements decoded from the iXBRL filings Bolagsverket publishes for free (EU high-value datasets since 3 Feb 2025). Query: /v1/eu/entreprise/SE/5560401977/comptes (10-digit organisationsnummer). EVERY digitally filed fiscal year: revenue, operating and net result, balance sheet (total assets, equity, debts), average employees and prior-year column as filed. Digital filing is optional in Sweden (~63% of reports): absence never means no accounts. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"orgnr": {"type": "string", "pattern": "^\\d{6}-?\\d{4}$", "maxLength": 500, "minLength": 1, "description": "10-digit Swedish organisationsnummer, with or without hyphen", "x-parameter-location": "path"}}, "required": ["orgnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-se-orgnr-evenements','Swedish company registry events (Bolagsverket weekly national file)','SE: Swedish company registry events from Bolagsverket''s official weekly national file (free EU high-value dataset) — credit risk signals: incorporation, ONGOING bankruptcy (konkurs), liquidation, company reconstruction, composition proceedings, merger or division, and deregistration with coded reason and date. Query: /v1/eu/entreprise/SE/5560012402/evenements (10-digit organisationsnummer). A registered company with no proceeding returns an explicit positive answer — the register is authoritative. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"orgnr": {"type": "string", "pattern": "^\\d{6}-?\\d{4}$", "maxLength": 500, "minLength": 1, "description": "10-digit Swedish organisationsnummer, with or without hyphen", "x-parameter-location": "path"}}, "required": ["orgnr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-dk-cvr-dirigeants','Danish company officers (CVR, Erhvervsstyrelsen, live) — management bodies and mandates','DK: Danish company officers and directors (deltagere) live from the official CVR register (Erhvervsstyrelsen system-to-system) by CVR number — governance and KYB: executive board (Direktion), board members (Bestyrelse) incl. deputies, election method, fully liable I/S or K/S partners and auditors — name, body, role, mandate dates. Active mandates by default; inclure_anciens=true adds ended ones where founders (stiftere) normally are. GDPR minimisation: never an address, never a personal identifier. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"cvr": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Danish CVR number", "x-parameter-location": "path"}, "inclure_anciens": {"type": "string", "enum": ["true"], "maxLength": 500, "minLength": 1, "description": "Also return ended mandates, each with its end date", "x-parameter-location": "query"}}, "required": ["cvr"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-cz-ico-insolvabilite','Czech company insolvency record (ISIR — Insolvenční rejstřík, since 2008)','CZ: Czech company insolvency from ISIR, the official insolvency register of Czechia, since 2008. Query: /v1/eu/entreprise/CZ/45274649/insolvabilite (8-digit IČO). Every proceeding — bankruptcy (konkurs), reorganisation (reorganizace): case number, court, status, dates, its 100 most recent events with document links. Publication is compulsory by law: no proceeding is an explicit positive answer. LEGAL PERSONS ONLY: a natural person''s IČO (sole trader — most Czech IČOs) is refused, never cleared. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"ico": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Czech IČO", "x-parameter-location": "path"}}, "required": ["ico"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-pl-krs-evenements','Polish company registry events (KRS daily bulletin) — liquidation, bankruptcy, filings, changes','PL: Polish company registry EVENTS from the official KRS daily bulletin (Ministry of Justice) — company monitoring for Poland. Query: /v1/eu/entreprise/PL/0000006865/evenements (KRS number). Liquidation, bankruptcy, restructuring, mergers, suspension/resumption, dissolution, tax arrears, enforcement, accounts filings, name/seat/capital changes, strike-off — each typed from a CLOSED list, dated, traced to its section, in a gap-free window. GDPR by design: no officer, no PESEL, no register free text. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"krs": {"type": "string", "pattern": "^\\d{10}$", "maxLength": 500, "minLength": 1, "description": "10-digit KRS number, leading zeros included", "x-parameter-location": "path"}}, "required": ["krs"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-pays-id-comptes-be','Company filings list — Belgium (NBB CBSO) and Finland (PRH XBRL filings)','BE: BE: every published annual-account deposit with its reference and filing metadata as published by the NBB (Authentic Data). FI: the fiscal years available from PRH XBRL filings (empty filings filtered out — every listed year carries figures). FI stock refreshed WEEKLY. Plus score_defaillance (statut non_evaluable + closed-list reasons: no default-risk score outside France — see GET /v1/lecture). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"pays": {"type": "string", "pattern": "^([Bb][Ee]|[Ff][Ii])$", "maxLength": 500, "minLength": 1, "description": "BE (Belgian annual accounts) or FI (Finnish XBRL-filed annual accounts, ~5% coverage)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^(\\d{10}|\\d{7}-\\d)$", "maxLength": 500, "minLength": 1, "description": "BE: 10-digit enterprise number (KBO/BCE). FI: Business ID NNNNNNN-N (e.g. 0103396-3)", "x-parameter-location": "path"}}, "required": ["pays", "id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-pays-id-comptes-fi','Company filings list — Belgium (NBB CBSO) and Finland (PRH XBRL filings)','FI: BE: every published annual-account deposit with its reference and filing metadata as published by the NBB (Authentic Data). FI: the fiscal years available from PRH XBRL filings (empty filings filtered out — every listed year carries figures). FI stock refreshed WEEKLY. Plus score_defaillance (statut non_evaluable + closed-list reasons: no default-risk score outside France — see GET /v1/lecture). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"pays": {"type": "string", "pattern": "^([Bb][Ee]|[Ff][Ii])$", "maxLength": 500, "minLength": 1, "description": "BE (Belgian annual accounts) or FI (Finnish XBRL-filed annual accounts, ~5% coverage)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^(\\d{10}|\\d{7}-\\d)$", "maxLength": 500, "minLength": 1, "description": "BE: 10-digit enterprise number (KBO/BCE). FI: Business ID NNNNNNN-N (e.g. 0103396-3)", "x-parameter-location": "path"}}, "required": ["pays", "id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-dk-id-comptes','Danish company filings list — fiscal years decoded from XBRL annual reports (Erhvervsstyrelsen)','DK: The fiscal years whose XBRL annual report (virk.dk publication index) has been decoded: closing dates, period, entity name, currency. Danish-taxonomy (fsa) filings only — IFRS/ESEF-only groups are not decoded; absence does not mean no accounts exist. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"id": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Danish CVR number", "x-parameter-location": "path"}}, "required": ["id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-sk-ico-comptes','Slovak company filings list — fiscal years decoded from structured statements (RÚZ, CC0)','SK: The fiscal years whose STRUCTURED financial statements at the Register účtovných závierok have been decoded: closing date, period, filing type, form model, statutory vs consolidated scope, official document link. A single closing date MAY appear more than once — an ordinary (Riadna) and an extraordinary (Mimoriadna) filing are two distinct filings, never merged; each entry carries the `type_depot` and `perimetre` that select it on the detail endpoint. PDF-only filings (every IFRS group among them) carry no structured data and are absent; absence does not mean no accounts exist. Sole traders are not served (GDPR minimisation). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"ico": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Slovak IČO", "x-parameter-location": "path"}}, "required": ["ico"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-gb-company-number-comptes','UK company accounts filings list — financial years decoded from iXBRL accounts (Companies House)','GB: The balance-sheet dates whose iXBRL annual accounts have been decoded, with period, entity name, currency, accounting framework and accounts type. Electronically filed accounts only (~75% of UK filings), depth accumulated since 2026-07 (the daily source file is retained 60 days) — absence does not mean no accounts exist. Open Government Licence v3.0. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number, 8 characters incl. leading zeros (00095407, SC123456, OC427207)", "x-parameter-location": "path"}}, "required": ["company_number"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-intelligence-siren','Company intelligence report — every block cross-referenced, closed-list signals, rule-based verdict','Identity, officers, financials with 3-year trend, sector positioning (NAF benchmarks), failure-risk score, BODACC alerts, sanctions screening (6 lists, company + officers), procurement (French DECP + EU TED), IP, cached capital structure, industrial-risk synthesis (Seveso/ICPE), AMF PSAN/SGP registers, HATVP lobbying summary, live VIES VAT check — plus closed-list signals traced to their register source, a deterministic verdict (solide/correct/fragile/critique/indeterminable) with `synthese.motifs_verdict` (closed-list codes that decided it) and `synthese.verdict_plafonne_par` (name-match doubts that capped a would-be « solide » at « correct » — when non-empty, read « correct » as « correct subject to verification »; v1.6), `synthese.reserves` / `portee` / `confiance_financiere` / `par_domaine` (v1.7: closed-list reading caveats, scope, score confidence band and a ten-domain projection of blocks already served — the verdict word is unchanged), and strengths/vigilance points. Ed25519-signed (v1.2). Carries the common `provenance[]` envelope (states and reading rules: GET /v1/lecture, free). AMF blacklist (since 2026-09-04): `risques.alertes_amf` serves the matches with score, level and qualification from the shared screening analyser; the vigilance signal `correspondance_liste_noire_amf` is raised only when a match weighs in the concordance table, otherwise the informative `rapprochement_liste_noire_amf_partiel` is emitted and no vigilance point is added. Since 2026-09-06 a failure score in the « vigilance » band raises `score_defaillance_vigilance` — a vigilance point and the verdict motif (negative, not damning: caps at « correct »), so a « correct » decided by the score alone is never served with an empty `points_vigilance`; a « correct » with no vigilance point now reads « solid not granted, see motifs_verdict ». Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-documents','List official documents filed at the INPI RNE registry','Legal deeds (actes: statutes, general-meeting minutes...) and filed annual accounts (bilans), each with document ID, label, filing date. Only documents the registry marks as public. Use the ID with /v1/documents/{type}/{id} to download the PDF. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-prospection','Multi-criteria prospecting over the full registry (100 active companies per paid page)','Up to 100 active companies (SIREN, name, NAF, legal form, workforce bracket, creation date, head-office postal code/city), stable SIREN order, page_suivante flag. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"naf": {"type": "string", "maxLength": 500, "minLength": 1, "description": "NAF/APE code or prefix (62, 62.01, 62.01Z)", "x-parameter-location": "query"}, "departement": {"type": "string", "maxLength": 500, "minLength": 1, "description": "French departement (75, 2A, 971…) — exclusive with code_postal", "x-parameter-location": "query"}, "code_postal": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Postal-code prefix (2 to 5 digits)", "x-parameter-location": "query"}, "forme_juridique": {"type": "string", "maxLength": 500, "minLength": 1, "description": "INSEE legal-category prefix (e.g. 54, 5499)", "x-parameter-location": "query"}, "effectif_min": {"type": "integer", "description": "Minimum workforce (mapped to INSEE brackets)", "x-parameter-location": "query"}, "effectif_max": {"type": "integer", "description": "effectif_max", "x-parameter-location": "query"}, "age_min": {"type": "integer", "description": "Minimum company age in years", "x-parameter-location": "query"}, "age_max": {"type": "integer", "description": "age_max", "x-parameter-location": "query"}, "rge": {"type": "boolean", "description": "true = active RGE certification", "x-parameter-location": "query"}, "egapro_min": {"type": "integer", "description": "Minimum gender-equality index (0-100)", "x-parameter-location": "query"}, "page": {"type": "integer", "minimum": 1, "maximum": 100, "description": "Page number — each page is one payment", "x-parameter-location": "query"}}, "required": []}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-sante','Business-health risk read-out (FR + EN, closed grid, official data only)','Risk read-out from official data: `synthese` (resume FR + resume_en, strengths, warning signs, missing data, verdict, activity trend, confidence level), `grille` (the reconciled evaluation grid, machine-readable codes) and `divergences_modele` (where deterministic guards overruled the model). A model only picks values from closed lists: no free text, no name and no figure of its own. WHAT TO EXPECT ON THIN FILES: entities that file no annual accounts — non-profits, sole traders, companies under a year old, ceased companies — return `verdict: "non_concluant"` with most grid fields set to `non_evaluable`; the prose then states explicitly that no accounts are available and whether that is normal at this age, and a ceased company is flagged with the `entreprise_administrativement_fermee` warning. Measured on a random sample of 47 SIREN: half of them are such files. Includes model, prompt version and cache status. Cached 7 days. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-score-defaillance-siren','Company default-risk score (transparent scorecard + BODACC override)','Credit risk scoring for a French company: a default-risk score (0-100) at ~12 months from a transparent scorecard — filed financial ratios (structure, profitability, liquidity, net cash, debt service, trend), company age, and a hard BODACC override (open insolvency/liquidation, or closure for insufficiency of assets). Returns the score, a qualitative band, every component with its threshold, and a confidence level. Decision-support indicator — NOT a solvency opinion or credit rating. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-secteur-code-naf-benchmarks','Sector benchmarks by NAF activity code (medians vs peers)','Sector benchmarks and sector statistics for a French NAF activity code (any level: division, groupe, classe, sous-classe): number of active companies, median company age (with quartiles), workforce-bracket distribution, and — when at least 5 companies file public accounts — median revenue, EBITDA margin, pre-tax result and debt ratio. Peer comparison in one call: place a company against its peers. Aggregates only, no personal data; sectors with fewer than 5 companies are excluded. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"code_naf": {"type": "string", "pattern": "^\\d{2}(\\.\\d{0,2}[A-Z]?)?$", "maxLength": 500, "minLength": 1, "description": "NAF code, any level: division (68), groupe (68.2), classe (68.20), sous-classe (68.20B)", "x-parameter-location": "path"}}, "required": ["code_naf"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-capital','Capital / ownership extracted by AI from public INPI articles of association','Ownership and share capital structure of a French company from the official INPI registry: AI extraction of the latest PUBLIC articles of association filed at INPI — share capital amount, legal form, shareholders (name, role, birth YEAR, ownership %), notable clauses, with a confidence level and the source document reference. Due diligence from public filed deeds — NOT a beneficial-ownership register (RBE) and not a beneficial-owner identification. Immutable document: extracted once, cached. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-pi','Industrial-property portfolio (trademarks, patents, designs) from INPI open data','Intellectual property portfolio of a French company from official INPI open data: patents, trademarks and designs — counts plus items with number, title/label, status, ISO dates (trademark filing/registration/expiry, patent publication) and classification (Nice/CIB/Locarno). Designs: one line per filing. An R&D / brand-value signal for due diligence. Trademarks and designs are most-recent-first; patents are NOT sorted upstream (liste_ordre). Inventor names are never returned. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-changements','New BODACC announcements since a date (poll-mode surveillance)','Company changes monitoring for a French company: the new official BODACC gazette announcements published SINCE a given date (?depuis=YYYY-MM-DD) — the poll endpoint for watchlist and portfolio surveillance. Returns the new announcements (insolvency, deregistration, sales, filings, changes) in reverse-chronological order. Note: detects new BODACC publications, not field-level edits of the Sirene/RNE profile (the monthly stock keeps no history). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}, "depuis": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$", "maxLength": 500, "minLength": 1, "description": "List announcements published on or after this date (YYYY-MM-DD)", "x-parameter-location": "query"}}, "required": ["siren", "depuis"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-facture-verifier','Invoice verification — cross-check the identifiers printed on a French invoice','Invoice verification for France — cross-check the identifiers PRINTED ON an invoice in one call: SIREN against the official registry (existence, active status, live), the VAT number on the invoice against the one computed from the SIREN AND live against VIES, the IBAN (ISO form, key digits, bank identified). Deterministic verdict coherent/incoherent/inverifiable, closed-list reasons. Flags a VAT that belongs to another company or a ceased supplier. Not a payee verification. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN printed on the invoice", "x-parameter-location": "query"}, "tva": {"type": "string", "maxLength": 20, "minLength": 1, "description": "VAT number printed on the invoice — cross-checked against the one computed from the SIREN AND live against VIES. At least one of tva/iban is required (400 otherwise)", "x-parameter-location": "query"}, "iban": {"type": "string", "maxLength": 40, "minLength": 1, "description": "IBAN printed on the invoice — ISO form + key digits + bank identification (never a holder-name check). At least one of tva/iban is required", "x-parameter-location": "query"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-facturation-dossier','Verify a supplier before payment — France (e-invoicing mandate, 1 September 2026)','Invoice verification and supplier verification — verify supplier before payment in France, the invoicing pack of the e-invoicing mandate France September 2026 (all VAT-liable companies must receive): legal identity, obligation dates, intra-EU VAT number checked LIVE against VIES, IBAN form + key check, bank identified, deterministic pret_a_facturer verdict, closed-list reasons. Not a payee verification: no holder name, no account existence check. A VIES outage never yields a false invalid. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN of the invoice recipient", "x-parameter-location": "query"}, "iban": {"type": "string", "maxLength": 40, "minLength": 1, "description": "Optional supplier IBAN — form check (structure + key) and bank identification before the first payment", "x-parameter-location": "query"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-facturation-prep','Prepare an e-invoice for a French recipient (mandate of 1 September 2026)','Supplier onboarding: PREPARE a compliant French e-invoice under the e-invoicing mandate France September 2026 (reception obligatory for every VAT-liable company; issuance phased GE/ETI 2026, SME 2027): legal name & form, status, computed intra-EU VAT number (with VIES pointer), establishments (SIRET) with addresses, NAF code, indicative obligation dates. Preparation only - Sirenic is not an accredited platform (PDP), never accesses the central directory and never issues or routes invoices. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated) of the invoice RECIPIENT", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-bodacc-recherche','Search BODACC legal announcements by criteria (family, date window, department)','Search French BODACC legal announcements by CRITERIA, not by company: pick a family (insolvency proceedings, deregistrations, sales, incorporations, accounts filings, conciliation...), a date window and optionally a department. Answers questions like: which companies entered insolvency proceedings in department 59 this week? Up to 100 announcements, newest first, each with its SIREN, court, town and structured judgment. Sole traders are excluded (their name is personal data) and counted. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"famille": {"type": "string", "enum": ["dpc", "modification", "creation", "radiation", "collective", "vente", "immatriculation", "divers", "conciliation", "retablissement_professionnel"], "maxLength": 500, "minLength": 1, "description": "Announcement family (closed list — these are the upstream BODACC codes, not translations): `collective` = insolvency/collective proceedings, `dpc` = accounts filings (the largest family, 26M), `retablissement_professionnel` = professional recovery. Note that `retablissement_professionnel` targets SOLE TRADERS, so this endpoint serves almost nothing for it and reports them under `exclues_personnes_physiques`.", "x-parameter-location": "query"}, "depuis": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Start of the publication window (YYYY-MM-DD). Required: there is no unbounded search.", "x-parameter-location": "query"}, "jusqu_a": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Optional end of the window (YYYY-MM-DD). The window may not exceed 366 days.", "x-parameter-location": "query"}, "departement": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Optional French department code: 01-95, 2A, 2B, 971-978.", "x-parameter-location": "query"}}, "required": ["famille", "depuis"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-dirigeant-recherche','Reverse director search by surname','Reverse search for company directors and officers in France: a people search by surname (?nom=) that lists the French companies where a person of that name holds or held an office, with each company SIREN, name and the person role — network mapping and due diligence on directors. Person data is limited to surname, first names, role and birth YEAR (French GDPR/INPI rules). Results are indicative: homonyms are not disambiguated and very common names are capped. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"nom": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Director surname — unsupported characters are stripped rather than rejected; 400 only when nothing searchable is left (1 to 100 characters once cleaned up).", "x-parameter-location": "query"}}, "required": ["nom"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-risques-industriels','Industrial-risk profile: classified ICPE facilities, Seveso status, risk synthesis','Industrial risk and environment profile of a French company from the official ICPE register (Géorisques/DGPR): classified facilities with Seveso status (upper/lower tier), authorisation regime, activity state, IED flag, nomenclature rubrics and a risk synthesis per SIREN — an ESG and environmental compliance signal on hazardous sites operated by the company. A company with no classified facility returns level aucun (still 200) — the clean answer is the signal. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-emploi','Hiring signals: actively hiring, posting volume, ROME families, pay-range share, Egapro index','Hiring signals for a French company, derived on demand from France Travail data (snapshot under 24 h, nothing stored): actively-hiring yes/no/unprovable, active-postings count (SIREN-keyed employer page when available, else strict name matching over known locations), top ROME occupation families, contract-type mix, share of postings displaying a pay amount - plus the Egapro gender-equality index and the INSEE workforce bracket. Aggregated signals only, never posting texts or recruiter contacts. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-facturation-dossier','Verify a supplier before payment — Belgium & Poland (incl. the White List account check)','European invoice verification and supplier verification for e-invoicing compliance in Belgium (mandate live since 1 Jan 2026) and Poland (KSeF): official registry identity, VAT check against VIES, Peppol reachability (BE), IBAN form + key check, bank identified and, in Poland, the official White List: is the IBAN DECLARED by the taxpayer? Paying an undeclared account over 15,000 PLN costs the buyer the VAT deduction and joint liability. Deterministic pret_a_facturer verdict, closed-list reasons. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"pays": {"type": "string", "enum": ["BE", "PL"], "maxLength": 500, "minLength": 1, "description": "Belgium or Poland (for France use /v1/facturation/dossier)", "x-parameter-location": "query"}, "id": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Belgian enterprise number or Polish NIP (10 digits)", "x-parameter-location": "query"}, "iban": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Payee IBAN — optional; form check (structure + key) plus bank identification, and in Poland it unlocks the White List account check", "x-parameter-location": "query"}}, "required": ["pays", "id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-pays-id-transactions-dirigeants-be','Belgian and German insider dealing (FSMA / BaFin, Art. 19 MAR): issuer-level aggregate, nobody named','BE: Director transactions and insider transactions at Belgian and German listed companies — managers transactions (directors'' dealings) under MAR Article 19, as notified to the FSMA and BaFin: are the company''s managers buying or selling? Issuer-level aggregate over a rolling 12 months — counts, gross buy and sell amounts, net flow, breakdown by declarer category, and the underlying notifications. BE: 10-digit enterprise number. DE: LEI or ISIN. No individual is ever named. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"pays": {"type": "string", "enum": ["BE", "DE"], "maxLength": 500, "minLength": 1, "description": "Belgium (FSMA) or Germany (BaFin)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^(\\d{10}|[0-9A-Z]{18}[0-9]{2}|[A-Z]{2}[0-9A-Z]{9}[0-9])$", "maxLength": 500, "minLength": 1, "description": "BE: 10-digit enterprise number. DE: LEI or ISIN — BaFin publishes no register number.", "x-parameter-location": "path"}, "depuis": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Start date (default: rolling 12 months)", "x-parameter-location": "query"}}, "required": ["pays", "id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-entreprise-pays-id-transactions-dirigeants-de','Belgian and German insider dealing (FSMA / BaFin, Art. 19 MAR): issuer-level aggregate, nobody named','DE: Director transactions and insider transactions at Belgian and German listed companies — managers transactions (directors'' dealings) under MAR Article 19, as notified to the FSMA and BaFin: are the company''s managers buying or selling? Issuer-level aggregate over a rolling 12 months — counts, gross buy and sell amounts, net flow, breakdown by declarer category, and the underlying notifications. BE: 10-digit enterprise number. DE: LEI or ISIN. No individual is ever named. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"pays": {"type": "string", "enum": ["BE", "DE"], "maxLength": 500, "minLength": 1, "description": "Belgium (FSMA) or Germany (BaFin)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^(\\d{10}|[0-9A-Z]{18}[0-9]{2}|[A-Z]{2}[0-9A-Z]{9}[0-9])$", "maxLength": 500, "minLength": 1, "description": "BE: 10-digit enterprise number. DE: LEI or ISIN — BaFin publishes no register number.", "x-parameter-location": "path"}, "depuis": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Start date (default: rolling 12 months)", "x-parameter-location": "query"}}, "required": ["pays", "id"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-agrements','Regulatory authorisations: payment/e-money (EBA), insurance (EIOPA), telecom (ARCEP)','Regulatory authorisation and licences held by a French company, by SIREN: payment institution, e-money institution, account-information provider, payment agent or exempt entity from the EBA PSD2 register (daily), insurance undertaking from EIOPA, telecom operator (electronic-communications operator, ARCEP). Returns authorisation dates, licensed PSD2 services, EEA passporting and withdrawals — a compliance check across three official registers. Not authorised is a paid answer too (200). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-association-rna','French association (loi 1901) profile by RNA number','Official profile of a French association (loi 1901) by RNA number (W + 9), from the RNA register (Ministry of the Interior, monthly): title, purpose and Waldec codes, nature, grouping, position (active/dissolved/deleted), creation, declaration, JO publication and dissolution dates, registered office, website, RUP number as declared, prefecture, and the SIREN when Sirene confirms it (categorie juridique 92xx). Covers associations WITHOUT a SIREN. No officer data. Excludes Alsace-Moselle. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"rna": {"type": "string", "minLength": 3, "maxLength": 14, "description": "RNA number (W + 9, e.g. W751004076) or legacy RNA id as published", "x-parameter-location": "path"}}, "required": ["rna"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-associations-recherche','Search French associations by name (RNA, top 20)','Search French associations (loi 1901) by name in the Répertoire national des associations (RNA, Ministry of the Interior): trigram similarity on the normalised title, optional postal-code, department and position filters (active, dissoute, supprimee), top 20 with score_confiance and the RNA number to use on /v1/association/{rna}. Associations with AND without a SIREN; the legacy file (no declaration since 2009) is flagged fichier_source: import. Excludes Alsace-Moselle (local law). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"q": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Association title, or an RNA number (resolved directly)", "x-parameter-location": "query"}, "code_postal": {"type": "string", "pattern": "^\\d{2,5}$", "maxLength": 500, "minLength": 1, "description": "Postal code or prefix (2-5 digits)", "x-parameter-location": "query"}, "departement": {"type": "string", "maxLength": 500, "minLength": 1, "description": "01-95, 2A, 2B or 971-989", "x-parameter-location": "query"}, "position": {"type": "string", "enum": ["active", "dissoute", "supprimee"], "maxLength": 500, "minLength": 1, "description": "Position filter", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-association-rna-annonces','JOAFE notices of a French association (creations, modifications, dissolutions)','Official Journal notices of a French association (JOAFE, DILA) by RNA number: creations, modifications (title, purpose, registered office), dissolutions, corrections — the association equivalent of BODACC notices, most recent first, with issue date, declaration date and prefecture, purpose themes and the PDF file name. Carries `couverture` (first and last loaded issue): no notice inside that window is a fact, not a gap. Weekly issue, loaded every Tuesday. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"rna": {"type": "string", "minLength": 3, "maxLength": 14, "description": "RNA number (W + 9, e.g. W011006690)", "x-parameter-location": "path"}}, "required": ["rna"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-marches-publics-ue','European public-procurement awards won (TED, identifier-matched)','European public procurement contract awards won by a French company, from TED (Tenders Electronic Daily, EU Publications Office): government contracts and tenders — buyer, country, subject, notice-level amount, CPV codes, co-winners and official notice link. Identifier-based matching only (SIREN/SIRET incl. spaced variants). Coverage: eForms award notices since 2023-10-25, above EU thresholds; ~57% of award notices carry a usable national identifier — an empty list is not proof of absence. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-entreprise-siren-lobbying','Lobbying profile from the official HATVP interest-representative register','Lobbying and influence profile of a French company from the official HATVP register of interest representatives — a transparency, governance and ESG due diligence signal: registration status, category, lobbying-expense brackets per fiscal year, staff count, recent subjects with intervention domains and action types, clients (for consulting firms), affiliations, declaration defaults and deregistrations. Organisation-level only — no personal data. Not registered is a meaningful answer (still 200). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-regulateurs-fr-alertes','French regulator (AMF) alerts: blacklists, PSAN registrations, licensed SGP','French financial regulator alerts and scam check against the official AMF blacklist: screen a name for unauthorized investment websites, scams and AMF impersonation, and look up PSAN crypto provider registrations and licensed asset management companies (SGP) by name or SIREN. A compliance screening of the regulator blacklists for agents vetting French counterparties in crypto and asset management. Official AMF open data (Licence Ouverte 2.0), refreshed daily. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"nom": {"type": "string", "minLength": 2, "maxLength": 100, "description": "Name to screen (site, brand, company) — required unless siren is given", "x-parameter-location": "query"}, "siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN for PSAN/SGP register lookup — required unless nom is given", "x-parameter-location": "query"}}, "required": ["nom"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-eu-agrements','EU financial authorisations (ESMA Registers, all EU/EEA countries)','EU financial authorisation lookup in the official ESMA Registers: search ~14,000 MiFID-regulated entities across the EU/EEA (investment firms, UCITS/AIFM managers) by name or LEI — authorisation status of the regulated entity, home and host member states, competent authority, authorisation dates. One integration covers all 27+ countries of Europe: an investment firm and regulated entity KYB check for the whole single market. Data freely available at the source (ESMA). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"q": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Entity name or 20-char LEI — unsupported characters are stripped rather than rejected (1 to 100 characters once cleaned up).", "x-parameter-location": "query"}, "pays": {"type": "string", "pattern": "^[A-Za-z]{2}$", "maxLength": 500, "minLength": 1, "description": "Optional ISO-3166 alpha-2 home-member-state filter", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-sanctions-check','Sanctions screening against the 6 official lists (UN, EU, OFAC, UK, FR, CH)','Matches with 0-100 confidence score and level (forte/possible/faible), matched alias, source list, regime, birth year, plus the inventory of loaded lists — each with its entry count, publication date and `precision_publication` saying whether that date is the upstream official publication or Sirenic''s ingestion date (OFAC publishes none). Never a bare yes/no. Carries the common `provenance[]` envelope (states and reading rules: GET /v1/lecture, free). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"name": {"type": "string", "minLength": 2, "maxLength": 100, "description": "Person or company name to screen", "x-parameter-location": "query"}, "birth_year": {"type": "string", "pattern": "^\\d{4}$", "maxLength": 500, "minLength": 1, "description": "Optional birth year to refine person matches", "x-parameter-location": "query"}}, "required": ["name"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-iban-verifier-iban','IBAN form check (structure + key) and bank identification from official registries — NOT a payee verification','IBAN verification and bank validation for SEPA payments: a FORM check to verify a supplier before payment — ISO 13616 structure + mod-97 key, plus bank identification from FREE official sources (FR via ACPR/REGAFI incl. LEI and SIREN; BE NBB; AT OeNB incl. LEI; NL BIC list; DE Bundesbank file). French BICs via GLEIF/SWIFT BIC-to-LEI. NOT a payee verification for instant payments: neither the holder name nor the account''s existence is checked (verification_titulaire: non_disponible). Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"iban": {"type": "string", "minLength": 15, "maxLength": 42, "description": "IBAN (spaces and dashes tolerated)", "x-parameter-location": "path"}}, "required": ["iban"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.sirenic-tva-verifier-numero','Validate an EU intra-community VAT number (VIES) before invoicing or paying','EU VAT validation against the official VIES service: validate any intra-community VAT number (all member states) for compliance and due diligence. This tax id check is the tax half of verify supplier before payment, and a required check under the e-invoicing mandate France September 2026. Returns valid/invalid/unavailable status with the VIES consultation identifier as proof — VAT number validation usable across Europe for KYB and supplier onboarding. Preserve coverage and provenance. Missing data is not zero; a name match is not proof of identity.','company','{"type": "object", "properties": {"numero": {"type": "string", "pattern": "^[A-Z]{2}[A-Za-z0-9+*]{2,12}$", "maxLength": 500, "minLength": 1, "description": "Full VAT number with country prefix, e.g. FR27552032534", "x-parameter-location": "path"}}, "required": ["numero"]}'::jsonb,'{"type": "object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('ae26f7f0-75fc-4d1b-b112-4ddb25c6e041','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/recherche','GET',0.002,true,true,'French company search and company lookup by name or SIREN in the official French company registry (INSEE Sirene / INPI RNE open data). Name search returns the top 10 matches with identity, SIREN, NAF code, city and active/ceased status, plus a score_confiance (0-1 match confidence) that helps disambiguate homonyms. The entry point to official data and company data on France: resolve a trading name to its SIREN identifier before pulling the full company profile, filings or financials.','{"type": "object", "properties": {"q": {"type": "string", "description": "Company name, or a French identifier (SIREN, SIRET, VAT) — spaced or labelled (\"SIREN : 552 032 534\") resolves directly. Unsupported characters are stripped, not rejected; 400 only if nothing searchable is left (1-100 chars once cleaned).", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type":"object"}','{"total_results": 10, "resultats": [{"siren": "552032534", "denomination": "DANONE", "statut_diffusion": "totale", "etat_administratif": "actif", "activite_principale": "70.10Z", "commune_siege": "PARIS", "code_postal_siege": "75009", "score_confiance": 1}], "source": "INSEE Sirene / INPI RNE via recherche-entreprises.api.gouv.fr, licence ouverte Etalab 2.0", "disclaimer": "Données issues de l''open data, fournies en l''état sans garantie. / Open data, provided as is without warranty.", "etages_abandonnes": [], "data_freshness": "stock Sirene mensuel (2026-08-01), dirigeants temps réel"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('bd7e87ef-21a9-53d0-93ee-94195d9aa584','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}','GET',0.005,true,true,'Full French company profile by SIREN: official company data from the French company registry (INSEE Sirene / INPI RNE). One company lookup returns legal name, legal form, head-office address, NAF code, workforce bracket, creation date, active or ceased status, officers with name and role, collective agreement and the computed intra-EU VAT number. The core KYB building block for verifying a French counterparty: registry facts for due diligence, compliance and onboarding checks.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}, "geo": {"type": "boolean", "description": "true = include GPS coordinates (WGS84) of establishments", "x-parameter-location": "query"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "nature_juridique": "5599", "activite_principale": "70.10Z", "categorie_entreprise": "GE", "tranche_effectif_salarie": "42", "date_creation": "1955-01-01", "etat_administratif": "actif", "siege": {"siret": "55203253400703", "adresse": "59 RUE LA FAYETTE 75009 PARIS", "code_postal": "75009", "commune": "PARIS"}, "dirigeants": [{"type": "personne_morale", "siren": "344366315", "denomination": "ERNST & YOUNG AUDIT", "fonction": "Commissaire aux comptes titulaire"}], "tva_intracommunautaire": "FR27552032534", "nombre_etablissements": 19, "index_egapro": [{"annee": 2025, "note": 86}], "source": "INSEE Sirene / INPI RNE via recherche-entreprises.api.gouv.fr, licence ouverte Etalab 2.0 ; index Egapro (ministère du Travail) et annuaire RGE (ADEME), licence ouverte Etalab 2.0", "data_freshness": "stock Sirene mensuel (2026-07-01), dirigeants temps réel"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
