query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('82d60dd2-4818-57fb-9681-473ec4859eba','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/kyb/{siren}','GET',0.15,true,true,'Complete KYB file for a French company (one call)','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "identite": {"denomination": "DANONE", "nature_juridique": "5599", "activite_principale": "70.10Z", "etat_administratif": "actif", "date_creation": "1955-01-01", "siege": {"siret": "55203253400703", "code_postal": "75009", "commune": "PARIS"}, "nombre_etablissements": 19}, "tva_intracommunautaire": "FR27552032534", "alertes_bodacc": {"procedures_collectives": [], "radiations": [], "total_annonces": 106}, "finances": {"nombre_exercices": 8, "exercices": [{"date_cloture": "2024-12-31", "chiffre_affaires": 1030000000, "resultat_net": 592000000}]}, "criblage_sanctions": {"statut": "correspondances_a_verifier", "cibles": [{"cible": "DANONE", "role": "entreprise", "nombre_correspondances": 0, "correspondances": [], "troncature": {"tronquee": false, "correspondances_servies": 0, "non_servies": 0, "niveau_non_servi": null, "prefiltre_sature": false, "note": null}}], "cibles_non_criblees": []}, "score_completude": 100, "blocs_manquants": [], "data_freshness": "identité : stock Sirene mensuel (2026-07-01)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('0e49f48b-ed5f-4f4c-95a3-aa672b875738','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/recherche','GET',0.003,true,true,'Search European companies across official registers (unified schema)','{"type": "object", "properties": {"q": {"type": "string", "description": "Company name — 2 to 100 characters once unsupported characters are stripped.", "x-parameter-location": "query"}, "pays": {"type": "string", "pattern": "^[A-Za-z]{2}$", "description": "Optional ISO-3166 alpha-2 country filter", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type":"object"}','{"nombre_resultats": 10, "registres_muets": [], "resultats": [{"pays": "NO", "id_national": "923609016", "denomination": "EQUINOR ASA", "statut": "actif", "ville": "STAVANGER", "registre": "Enhetsregisteret (Brønnøysundregistrene)", "correspondance": "registre_local", "score_confiance": 1}], "pays_couverts": [{"pays": "NO", "registre": "Enhetsregisteret (Brønnøysundregistrene)", "mode": "base locale", "entites": 1168483}], "source": "Registres officiels : Brønnøysundregistrene (NO, NLOD), e-Business Register (EE, CC-BY 4.0), Uzņēmumu reģistrs (LV), KBO/BCE (BE), CVR (DK), Companies House (GB, OGL), ARES (CZ), Register právnických osôb (SK, CC-BY 4.0), PRH/YTJ (FI, CC-BY 4.0), Krajowy Rejestr Sądowy (PL), Zefix (CH, OGD), Bolagsverket (SE), GLEIF (CC0)", "disclaimer": "Données rediffusées telles que publiées par les registres officiels, dans un schéma unifié ; `statut` est une normalisation en 3 valeurs, le libellé source est conservé dans `statut_detail`. / Official register data as published, unified schema; `statut` is a 3-value normalization."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('4e02bf35-6cbd-5231-88f7-1cf9a3893d7d','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/{pays}/{id}','GET',0.01,true,true,'Unified European company profile','{"type": "object", "properties": {"pays": {"type": "string", "pattern": "^[A-Za-z]{2}$", "description": "ISO-3166 alpha-2 country code (NO, EE, LV, BE, CH, CZ, SK, FI, PL; DK/GB when enabled)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^[A-Za-z0-9.-]{1,20}$", "description": "National register identifier", "x-parameter-location": "path"}}, "required": ["pays", "id"]}'::jsonb,'{"type":"object"}','{"pays": "GB", "registre": "Companies House", "id_national": "00000006", "lei": null, "denomination": "MARINE AND GENERAL MUTUAL LIFE ASSURANCE SOCIETY", "forme_juridique": {"code": "private-unlimited-nsc", "libelle": null}, "statut": "cesse", "statut_detail": "dissolved", "date_creation": "1862-10-25", "adresse_siege": {"adresse": "Cms Cameron Mckenna Llp Cannon Place", "code_postal": "EC4N 6AF", "ville": "London", "pays": "GB"}, "activite": {"nomenclature": "SIC-2007", "code": "65110", "libelle": null}, "identifiants": {"tva": null, "lei": null}, "lien_registre": "https://find-and-update.company-information.service.gov.uk/company/00000006", "data_freshness": "Companies House temps réel (cache 24 h)", "source": "Registres officiels : Brønnøysundregistrene (NO, NLOD), e-Business Register (EE, CC-BY 4.0), Uzņēmumu reģistrs (LV), KBO/BCE (BE), CVR (DK), Companies House (GB, OGL), ARES (CZ), Register právnických osôb (SK, CC-BY 4.0), PRH/YTJ (FI, CC-BY 4.0), Krajowy Rejestr Sądowy (PL), Zefix (CH, OGD), Bolagsverket (SE), GLEIF (CC0)", "disclaimer": "Données rediffusées telles que publiées par les registres officiels, dans un schéma unifié ; `statut` est une normalisation en 3 valeurs, le libellé source est conservé dans `statut_detail`. / Official register data as published, unified schema; `statut` is a 3-value normalization."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('33828a2e-2529-5d2a-99ac-4f69a9b17910','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/etablissements','GET',0.003,true,true,'List establishments (SIRET) of a company. All establishments (SIRET) of a French company: the complete list of business locations registered under one SIREN, official data from the French company registry (INSEE Sirene), head office and branches alike, each with its address and open or closed status. Use it to map the branches and addresses of a company across France, or to check whether a given SIRET is still open. The SIREN identifies the legal entity; the SIRET identifies each of its establishments.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "nombre_etablissements": 19, "etablissements": [{"siret": "55203253400703", "est_siege": true, "adresse": "59 RUE LA FAYETTE 75009 PARIS", "code_postal": "75009", "commune": "PARIS", "etat_administratif": "actif", "activite_principale": "70.10Z", "date_creation": "2025-08-19", "date_fermeture": null, "enseignes": [], "tranche_effectif_salarie": "NN"}], "source": "INSEE Sirene / INPI RNE via recherche-entreprises.api.gouv.fr, licence ouverte Etalab 2.0", "disclaimer": "Données issues de l''open data, fournies en l''état sans garantie. / Open data, provided as is without warranty.", "data_freshness": "stock Sirene mensuel (2026-07-01), dirigeants temps réel"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('409b41ec-9748-5258-8f71-e2b1251c63d6','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/alertes','GET',0.01,true,true,'Legal alerts from BODACC (insolvency, deregistration, business sales). Announcements grouped by family (procedures collectives, radiations, ventes/cessions), most recent first, with judgment details. Each announcement carries `role`: `sujet` (this company is the debtor), `partie_citee` or `indetermine`. Since 2026-09-04, insolvency notices of ANOTHER company that merely cite this one as a party (creditor bank, counterparty) are served apart in `mentions_comme_partie` with the real debtor''s name (`sujet_annonce`), and count towards NO verdict — a creditor listed in a debtor''s conciliation judgment used to be scored as if it were in proceedings itself. `denomination` is the Sirene legal name (`denomination_source`), never the trade label of the latest notice.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "procedures_collectives": [], "radiations": [], "ventes_cessions": [], "autres_annonces": {"Modifications diverses": 63, "Dépôts des comptes": 37}, "total_annonces": 106, "consulte_le": "2026-07-29T07:28:49.560Z", "source": "BODACC (DILA) via bodacc-datadila.opendatasoft.com, licence ouverte Etalab 2.0", "disclaimer": "Annonces officielles telles que publiées ; les avis rectificatifs et annulations sont restitués avec leur type, sans fusion. / Official announcements as published; rectifications and cancellations carry their type.", "data_freshness": "BODACC temps réel (API DILA), cache 24 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('93610769-e3fb-5b45-b188-0b631a2b6863','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/contentieux','GET',0.01,true,true,'Commercial-court decisions linked to the company (Judilibre open data). Commercial-court decisions linked to the SIREN, most recent first (100 max, `tronque` beyond): court and code, date, docket number, closed-list `nature` and `role`, the other legal entities involved (SIREN + Sirene name), `redondante_bodacc` for insolvency judgments already served by /alertes, and the official Judilibre URL. Plus counts, the measured coverage (61.8% of decisions carry a usable identifier) and the source update date. Never a text, a natural person''s name or an amount.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "exhaustivite": "partielle", "avertissement": "Une absence de résultat ne vaut pas absence de contentieux.", "synthese": {"nombre_decisions": 1, "par_nature": {"condamnation_ou_injonction_a_payer": 1}}, "decisions": [{"id_judilibre": "69f4703ccdc6046d4731b4af", "date": "2026-04-30", "juridiction": "Tribunal de commerce d''Orléans", "nature": "condamnation_ou_injonction_a_payer", "role": "demandeur", "mode_rattachement": "identifiant_etiquete", "confiance": "certain", "url_officielle": "https://www.courdecassation.fr/decision/69f4703ccdc6046d4731b4af"}], "tronque": false, "source": "Cour de cassation — base Judilibre (open data, source juritcom), Licence Ouverte 2.0 ; dernière mise à jour de notre stock : 2026-09-10.", "consulte_le": "2026-09-10T11:44:00Z", "disclaimer": "Liens décision ↔ société par identifiant RCS/SIREN ; couverture partielle mesurée ; aucune donnée de personne physique. / Partial measured coverage; no natural-person data.", "data_freshness": "stock Judilibre tcom collecté quotidiennement (dernier passage réussi : 2026-09-10) ; identité Sirene"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('17c8e095-cbf3-52bd-868f-3dd2c0c8757f','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/marches-publics','GET',0.01,true,true,'Public procurement contracts won (official DECP data). Aggregates (count and total amount as TWO bounds — raw per published row, and deduplicated per (buyer, date, amount, CPV) key —, contracts still running, next expiry) plus the 100 most recent contracts with buyer identity resolved, estimated end dates and a per-row publication status (unique, multi-platform, repeated, per-establishment, amendment) with linked rows.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "siren", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "130031487", "nombre_marches": 26, "montant_total": 4943495.5, "nombre_accords_cadres": 18, "montant_plafonds_accords_cadres": 4162376, "montant_hors_accords_cadres": 781119.5, "nombre_montants_enveloppe": 20, "nombre_modalites_connues": 26, "montant_enveloppes": 4234476, "montant_prix_fermes": 709019.5, "nombre_sous_traitance_connue": 26, "nombre_sous_traitance_declaree": 16, "nombre_sous_traitants": 2, "montant_sous_traite": 20910.24, "premier_marche": "2023-06-07", "dernier_marche": "2026-06-01", "marches_en_cours": 18, "prochaine_echeance": "2026-12-17", "marches": [{"id": "20262026100", "objet": "ACTIONS DE FORMATION POUR LA SOUS SPECIALITE E1D ESPACES VERTS LOT 7 POUR LE COMPTE DE LA DELEGATION PAYS DE LA LOIRE DU CNFPT", "montant": 100000, "montant_modifie": null, "lot_numero": 7, "co_traitance": false, "nombre_titulaires": 1, "groupement": null, "date_notification": "2026-06-01", "duree_mois": 24, "duree_mois_modifiee": null, "date_fin_estimee": "2028-06-01", "regime": "2022", "accord_cadre": true, "montant_est_enveloppe": true, "modalites_execution": "Bons de commande", "ccag": "Fournitures courantes et services", "types_prix": "Définitif révisable", "marche_innovant": false, "avance": {"attribuee": false, "taux": 0}, "origine": {"ue": 0, "france": 0}, "plateforme_source": "DGFIP – PES MARCHÉ", "avenant": null, "sous_traitance": {"declaree": false, "acte_id": null, "montant": null, "part_du_montant": null, "duree_mois": null, "date_notification": null, "variation_prix": null, "sous_traitant": null}, "offres_recues": 1, "acheteur": {"siret": "18001404502245", "nom": "CENTRE NATIONAL DE LA FONCTION PUBLIQUE TERRITORIALE"}, "nature": "Marché", "procedure": "Procédure adaptée", "code_cpv": "80530000-8", "lieu_execution": "49000"}], "liste_tronquee": false, "source": "Données essentielles de la commande publique (DECP consolidées) via data.economie.gouv.fr, licence ouverte 2.0"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7a29d4c7-cfe1-5496-b9d0-70e7073385c8','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/marches/expirations','GET',0.05,true,true,'Tender anticipation: French public contracts expiring within a window. Contracts whose ESTIMATED end date (notification + initially declared duration; duration amendments are absent from the DECP source) falls inside the window, sorted by end date: buyer (SIRET + resolved name), incumbent holders, amount (after amendment when published), framework-agreement flag, CPV, department. Buyers typically re-tender 4-9 months before expiry. An empty list is scoped honestly: contracts under EUR 40k excl. VAT are unpublished.','{"type": "object", "properties": {"cpv": {"type": "string", "pattern": "^\\d{2,8}$", "maxLength": 500, "minLength": 1, "description": "CPV prefix (45 = construction works)", "x-parameter-location": "query"}, "departement": {"type": "string", "pattern": "^(?:0[1-9]|1\\d|2[1-9]|[3-8]\\d|9[0-5]|2[AB]|97[1-8]|98[4-8])$", "maxLength": 500, "minLength": 1, "description": "French department code (01-95, 2A, 2B, 971-978, 984-988)", "x-parameter-location": "query"}, "fenetre_mois": {"type": "integer", "minimum": 1, "maximum": 24, "description": "Window in months (default 12)", "x-parameter-location": "query"}, "page": {"type": "integer", "minimum": 1, "maximum": 500, "description": "50 contracts per page", "x-parameter-location": "query"}}, "required": []}'::jsonb,'{"type":"object"}','{"filtres": {"cpv": "45", "departement": null, "fenetre_mois": 6}, "total_marches": 34249, "page": 1, "pages": 685, "marches": [{"id": "2777529", "objet": "Travaux de menuiserie pour l''accueil de la DRFIP 44", "acheteur": {"siret": "13001292500017", "nom": "DIRECTION REGIONALE FINANCES PUBLIQUES PAYS DE LA LOIRE ET DEPARTEMENT LOIRE ATLANTIQUE"}, "montant": 9788.8, "accord_cadre": false, "montant_est_enveloppe": true, "modalites_execution": "Marchés subséquents", "sous_traitance_declaree": false, "lot_numero": null, "date_notification": "2025-09-02", "duree_mois": 12, "date_fin_estimee": "2026-09-02", "code_cpv": "45421100-5", "departement": null, "titulaires_sortants": [{"siren": "501383251", "nom": "SOGEA ATLANTIQUE BTP"}]}]}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('9daae39c-b47b-5877-8a59-4987bef1d1dd','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/acheteur/{siret}/profil','GET',0.02,true,true,'Procurement profile of a French public buyer. Contract counts and amounts, activity by year (5y), top CPV segments, incumbent suppliers with contracts expiring within 18 months, framework-agreement share, average bids received per tender and median data-publication delay.','{"type": "object", "properties": {"siret": {"type": "string", "pattern": "^\\d{14}$", "maxLength": 500, "minLength": 1, "description": "14-digit SIRET of the buyer (Luhn-checked)", "x-parameter-location": "path"}}, "required": ["siret"]}'::jsonb,'{"type":"object"}','{"acheteur": {"siret": "26310012500016", "siren": "263100125", "nom": "CENTRE HOSPITALIER UNIVERSITAIRE DE TOULOUSE"}, "nombre_marches": 5723, "montant_total": 11823128968.9, "montant_moyen": 2065897, "marches_en_cours": 4830, "echeances_12_mois": 1167, "prochaine_echeance": "2026-09-05", "habitudes": {"part_accords_cadres_pct": 78.4, "offres_recues_moyenne": 3.5, "delai_publication_median_jours": 11, "part_montants_enveloppe_pct": 79.8, "modalites_connues": 5723, "part_sous_traitance_declaree_pct": 77.6, "sous_traitance_connue": 5723, "part_avances_pct": 57.4, "avance_connue": 5723, "ccag_dominant": "Fournitures courantes et services", "types_prix_dominant": "Définitif révisable", "plateforme_publication_dominante": "DGFIP – PES MARCHÉ"}, "top_cpv": [{"cpv4": "3300", "nombre": 3002}], "titulaires_principaux": [{"siren": "433944485", "nom": "ARROW GENERIQUES", "nombre_marches": 164, "marches_expirant_18_mois": 67}]}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
