INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('e0b5bbb7-d674-527a-88ca-3163574ffef9','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/ES/{hoja}/actes','GET',0.02,true,true,'Spanish company acts from the BORME gazette (Registro Mercantil, section A), by hoja registral. Spanish company acts from the official BORME gazette (Registro Mercantil, section A) by hoja registral — the register key, e.g. VI-23141: incorporations, officer appointments and dismissals (role + name), capital changes, mergers, dissolutions, insolvency. Daily filings flow since 2009, newest first (100 max + total count). Spanish personal IDs (DNI/NIE) and natural-person sole-shareholder names are redacted at ingestion. Basado en datos de la Agencia Estatal Boletin Oficial del Estado (boe.es).','{"type": "object", "properties": {"hoja": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9 .-]{1,24}$", "maxLength": 500, "minLength": 1, "description": "Hoja registral (register-sheet key, e.g. VI-23141) — get it from /v1/eu/recherche?pays=ES. The BORME does not publish the NIF; the hoja is the native key.", "x-parameter-location": "path"}}, "required": ["hoja"]}'::jsonb,'{"type":"object"}','{"pays": "ES", "hoja": "VI-14412", "denomination": "OSG IBERICA TOOLING, SOCIEDAD LIMITADA", "nif": null, "rattachement_nif": "non disponible — le BORME (sección A) ne publie pas le NIF", "nombre_actes": 1, "actes_tronques": false, "actes": [{"fecha": "2026-07-23", "numero": 344928, "provincia": "ARABA/ÁLAVA", "id_document": "BORME-A-2026-140-01", "types": ["fusion por absorcion"], "corps": "Fusión por absorción. Sociedades absorbidas: OSG NST IBERICA SOCIEDAD LIMITADA.  Datos registrales. S 8 , H VI 14412, I/A 32 (15.07.26)."}], "source": "BORME sección A (actos inscritos) — Basado en datos de la Agencia Estatal Boletín Oficial del Estado (https://www.boe.es)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('ade61e90-e0a2-53d4-9267-7e41fa925022','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/NO/{id}/comptes','GET',0.02,true,true,'Norwegian annual accounts (Regnskapsregisteret) — latest year live + every year accumulated since 2026-07. Norwegian company annual accounts and financial statements from Norway''s official Regnskapsregisteret (Brønnøysundregistrene, Brreg, NLOD 2.0). Query: /v1/eu/entreprise/NO/923609016/comptes (9-digit organisasjonsnummer). Latest filed fiscal year live from the register plus earlier years collected since 2026-07 — financials: balance sheet (assets, equity, debts), P&L (operating income and result, net result) in the filing currency (can be USD). Banks and insurers are not served by the source.','{"type": "object", "properties": {"id": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit Norwegian organisasjonsnummer (no spaces)", "x-parameter-location": "path"}}, "required": ["id"]}'::jsonb,'{"type":"object"}','{"pays": "NO", "id_national": "923609016", "nombre_exercices": 1, "exercices": [{"date_cloture": "2024-12-31", "debut_exercice": "2024-01-01", "devise": "USD", "oppstillingsplan": "store", "petite_entreprise": false, "bilan": {"total_actif": 109150000000, "capitaux_propres": 41090000000, "dettes": 68060000000}, "resultat": {"produits_exploitation": 72543000000, "resultat_net": 8141000000}, "collecte_le": "2026-07-29"}], "source": "Data from Brønnøysundregistrene — Regnskapsregisteret (data.brreg.no), licence NLOD 2.0", "licence": "Data from Brønnøysundregistrene, NLOD 2.0", "disclaimer": "Le Regnskapsregisteret ouvert ne sert que le DERNIER exercice déposé", "score_defaillance": {"statut": "non_evaluable", "pays": "NO", "version": "evaluabilite-v1", "raisons": ["axes_hors_d_atteinte", "historique_a_la_demande", "bareme_non_calibre_pour_le_pays"], "postes_normalises": ["produits_exploitation"], "ratios_hors_d_atteinte": ["marge_ebe"], "flux_insolvabilite": "stock", "lecture": "Aucun score pour cette entité : `raisons` dit, en liste fermée, ce qui manque au barème pour ce pays. Ni score bas, ni signal, ni absence de risque : aucune bande, aucun classement. / No score for this entity: `raisons` lists, closed, what the scorecard lacks for this country. Neither a low score, nor a signal, nor an absence of risk: no band, no ranking."}}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('1619a1c6-8b39-511e-9ee8-ab3bf57a83ac','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/NO/{id}/evenements','GET',0.02,true,true,'Norwegian legal events (Enhetsregisteret) — bankruptcy, winding-up, strike-off. Norwegian company legal events from the official Enhetsregisteret (Brreg, NLOD 2.0) for insolvency and credit risk monitoring: bankruptcy (konkurs, with the registered date), voluntary or compulsory liquidation, and strike-off, plus current flags checked live. 9-digit organisasjonsnummer. A live-verified company with no flag gets an explicit positive answer. Coarser than France''s BODACC: no ruling text, no court; undated events carry an upper-bound date. Legal persons only, never individuals.','{"type": "object", "properties": {"id": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit Norwegian organisasjonsnummer (no spaces)", "x-parameter-location": "path"}}, "required": ["id"]}'::jsonb,'{"type":"object"}','{"pays": "NO", "id_national": "926455249", "denomination": "123 HOLDING AS", "forme_juridique": "AS", "etat_courant": {"faillite": true, "faillite_date": "2026-02-27", "radie_le": null, "verifie_en_direct": true, "lecture_directe": "verifiee"}, "evenements": [{"type": "faillite", "libelle": "Bankruptcy opened (konkurs)", "date": "2026-02-27", "origine_date": "registre", "date_au_plus_tard": false}], "nombre_evenements": 1, "aucun_evenement": false, "source": "Data from Brønnøysundregistrene — Enhetsregisteret (data.brreg.no), licence NLOD 2.0", "licence": "Data from Brønnøysundregistrene, NLOD 2.0"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('b535c580-b983-5c83-a58a-796360e6df74','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/GB/{company_number}/dirigeants','GET',0.01,true,true,'UK company officers (Companies House, live) — active directors and secretaries. UK company officers live from Companies House, the official UK company registry, by company number (e.g. GB/00102498): active directors and secretaries with role, appointment date, nationality, occupation, country of residence and month+year of birth only — never a correspondence address (GDPR minimisation). Resigned-officer count included. Built for KYB and due diligence on director appointments and governance. Contains public sector information licensed under the Open Government Licence v3.0.','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number (8 characters incl. leading zeros, e.g. 00102498, SC123456, NI017460)", "x-parameter-location": "path"}}, "required": ["company_number"]}'::jsonb,'{"type":"object"}','{"pays": "GB", "company_number": "00000006", "nombre_actifs": 0, "nombre_demissionnes": 49, "tronque": false, "dirigeants": [{"nom": "<nom du dirigeant>", "fonction": "director", "nomme_le": null, "nationalite": null, "profession": null, "pays_de_residence": null, "naissance": null}], "source": "Companies House (api.company-information.service.gov.uk). Contains public sector information licensed under the Open Government Licence v3.0 (Companies House).", "data_freshness": "Companies House temps réel (cache 24 h)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('29d36ea3-6900-5f50-a67e-4b4c2bcbe3b0','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/GB/{company_number}/beneficiaires-effectifs','GET',0.02,true,true,'UK beneficial owners (PSC register, Companies House, live). UK beneficial owners (PSC, persons with significant control) live from Companies House for AML, KYB and compliance: individual and corporate-entity PSCs with natures of control (ownership/voting bands), notification dates, plus official PSC statements. Ceased PSCs excluded by default (inclure_cesses=true adds them with their ceased date). Beyond French-registry parity — France exposes no open UBO register. Month+year of birth only, no addresses. Open Government Licence v3.0 (Companies House).','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number", "x-parameter-location": "path"}, "inclure_cesses": {"type": "string", "enum": ["true"], "maxLength": 500, "minLength": 1, "description": "Also return ceased PSCs (with their ceased_on date)", "x-parameter-location": "query"}}, "required": ["company_number"]}'::jsonb,'{"type":"object"}','{"pays": "GB", "company_number": "00446915", "nombre_actifs": 1, "nombre_cesses": 0, "exemption_possible": false, "beneficiaires": [{"type": "entite", "nom": "Bp International Limited", "notifie_le": "2016-04-06", "natures_de_controle": ["ownership-of-shares-75-to-100-percent"], "identification": {"forme_juridique": "Limited By Shares", "registre": "Companies House", "numero_registre": "00542515"}}], "declarations": [], "source": "Companies House (api.company-information.service.gov.uk). Contains public sector information licensed under the Open Government Licence v3.0 (Companies House).", "data_freshness": "Companies House temps réel (cache 24 h)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('fbbe0eff-7025-54ae-a3d2-f970cefc295c','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/GB/{company_number}/insolvabilite','GET',0.02,true,true,'UK company insolvency record (Companies House, live). UK company insolvency record for credit risk and compliance screening, live from Companies House by company number: liquidation (compulsory or voluntary), administration, receivership and other cases with their dates and insolvency practitioners (name and role only, no addresses). A company with NO recorded case returns an explicit positive answer (200, aucune_procedure) — the register is authoritative, an empty record is a fact. Open Government Licence v3.0 (Companies House).','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number", "x-parameter-location": "path"}}, "required": ["company_number"]}'::jsonb,'{"type":"object"}','{"pays": "GB", "company_number": "NI017460", "aucune_procedure": false, "statuts": ["liquidation"], "cas": [{"type": "compulsory-liquidation", "numero": "1", "dates": [{"type": "wound-up-on", "date": "2008-11-20"}], "praticiens": [{"nom": "<nom du praticien de l''insolvabilité>", "role": "practitioner", "nomme_le": null, "fin_de_mission_le": null}], "notes": []}], "source": "Companies House (api.company-information.service.gov.uk). Contains public sector information licensed under the Open Government Licence v3.0 (Companies House).", "data_freshness": "Companies House temps réel (cache 24 h)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('6a033043-c81d-53c7-98f2-e6f91976f135','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/LV/{regnr}/comptes','GET',0.03,true,true,'Latvian annual accounts (Uzņēmumu reģistrs / VID filings) — every filed fiscal year in one call. Latvian company annual accounts — official financial statements from VID filings via the Uzņēmumu reģistrs open data of Latvia (CC0, daily). Query: /v1/eu/entreprise/LV/40003032065/comptes (11-digit registration number). EVERY filed fiscal year in one call: balance sheet, profit and loss (revenue, net income), cash flow when filed, employees, as published (EUR, LVL before 2014; statutory and consolidated filings kept apart). Null = not published, never zero.','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type":"object"}','{"pays": "LV", "id_national": "40003032949", "nombre_exercices": 2, "exercices": [{"date_cloture": "2025-12-31", "exercice": 2025, "perimetre": "statutaire", "devise": "EUR", "arrondi": "THOUSANDS", "employes": 1389, "bilan": {"total_actif": 4189397}, "compte_resultat": {"chiffre_affaires": 949824}, "flux_tresorerie": {"flux_exploitation": 376739}}], "source": "Uzņēmumu reģistrs / VID — open data data.gov.lv", "licence": "Uzņēmumu reģistrs / VID, data.gov.lv, CC0 1.0", "disclaimer": "Postes clés des rapports annuels déposés au VID, tels que publiés par l''Uzņēmumu reģistrs (CC0)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('f2a134b4-d2b9-5e7b-a5a4-fc4b3f634dcb','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/LV/{regnr}/insolvabilite','GET',0.02,true,true,'Latvian company insolvency record (Uzņēmumu reģistrs, daily national photo). Latvian company insolvency record from the official Uzņēmumu reģistrs open data (CC0, daily photo since 2008), built for credit risk and compliance screening: insolvency and legal protection proceedings in Latvia with start/end dates, resolution, court and case number. A registered company with NO proceeding returns an explicit positive answer (200, aucune_procedure: true) — the register is authoritative. 11-digit registration number.','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type":"object"}','{"pays": "LV", "id_national": "40103144555", "aucune_procedure": false, "procedures": [{"proceeding_id": 90134947, "debiteur": "SIA \"NaviFleet\"", "debut": "2025-10-14", "fin": null, "forme": "LEGAL_PROTECTION", "type": "NATIONAL", "resolution": null, "numero_affaire": "C771723525", "tribunal": "Rīgas pilsētas tiesa"}], "source": "Uzņēmumu reģistrs / VID — open data data.gov.lv (Gada pārskatu finanšu dati, Maksātnespējas procesi, Amatpersonas, Patiesie labuma guvēji), licence CC0 1.0", "data_freshness": "photo quotidienne data.gov.lv pré-ingérée (MAJ amont ~20:25 UTC)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED