INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('8023d7aa-b9fa-5a9e-a491-04dee234353c','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/LV/{regnr}/evenements','GET',0.02,true,true,'Latvian company legal events (Uzņēmumu reģistrs — liquidations, reorganisations, VID suspensions, securing measures). Latvian company legal events from the official Uzņēmumu reģistrs open data (CC0, daily photo): liquidations and activity terminations (incl. by court or tax authority), mergers, acquisitions, divisions and transformations with the other company''s number, VID activity suspensions, securing measures (prohibitions, liens, attachments) with the registering institution. Closed-list types plus source code and wording. A registered company with no event gets aucun_evenement: true. 11-digit number.','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type":"object"}','{"pays": "LV", "id_national": "50203219311", "nombre_evenements": 2, "aucun_evenement": false, "evenements": [{"famille": "liquidation", "type": "cessation_activite", "type_source": "ACTIVITY_TERMINATED", "libelle_source": "Darbības izbeigšana", "date": "2026-08-31", "fondement": "Latvijas Republikas Uzņēmumu reģistra valsts notāra 03.07.2026. lēmums Nr.6-12/53992", "role": "objet", "societe_liee": null, "numero_affaire": null, "institution": null, "inscrit_le": "2026-08-31T11:37:11Z"}, {"famille": "surete", "type": "interdiction", "type_source": "PROHIBITION", "libelle_source": "Aizliegums", "date": "2025-07-28", "fondement": "Piemērots aizliegums reorganizācijai un dalībnieku maiņai", "role": "objet", "societe_liee": null, "numero_affaire": "32.1/17.22.1/25774", "institution": {"type": "administration_fiscale", "nom": "Valsts ieņēmumu dienests", "regnr": "90000069281"}, "inscrit_le": null}], "licence": "Uzņēmumu reģistrs / VID, data.gov.lv, CC0 1.0"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('bb94147a-acef-5ada-ab0b-b9d3d8c0581f','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/LV/{regnr}/associes','GET',0.02,true,true,'Latvian company members and shareholders (Uzņēmumu reģistrs — corporate holders named, natural persons counted). Latvian company members and shareholders from the official Uzņēmumu reģistrs open data (CC0, daily): SIA members (parts) and AS registered shareholders with number of shares, nominal value and currency as published (LVL before 2014), votes, share of nominal capital and holding start date. Corporate holders are named with their registration number; natural persons are COUNTED, never named (GDPR); dematerialised shares show the depository only. Group links for KYB. 11-digit number.','{"type": "object", "properties": {"regnr": {"type": "string", "pattern": "^\\d{11}$", "maxLength": 500, "minLength": 1, "description": "11-digit Latvian registration number", "x-parameter-location": "path"}}, "required": ["regnr"]}'::jsonb,'{"type":"object"}','{"pays": "LV", "id_national": "40103774127", "aucun_associe_inscrit": false, "nombre_associes": 2, "associes": [{"type": "personne_morale", "nom": "JC, Sabiedrība ar ierobežotu atbildību", "regnr_entite": "40003666739", "titres": {"nature": "parts_sociales", "nombre": 1530, "valeur_nominale": 1, "devise": "EUR", "votes": null, "type_actions": null}, "part_capital_pct": 51, "coproprietaires": null, "actionnaires_non_publies": false, "depuis": "2014-03-27", "inscrit_le": "2014-03-27", "modifie_le": "2014-03-27T16:38:01Z"}, {"type": "personne_physique", "nom": null, "regnr_entite": null, "titres": {"nature": "parts_sociales", "nombre": 1470, "valeur_nominale": 1, "devise": "EUR", "votes": null, "type_actions": null}, "part_capital_pct": 49, "coproprietaires": null, "actionnaires_non_publies": false, "depuis": "2014-03-27", "inscrit_le": "2014-03-27", "modifie_le": "2014-03-27T16:38:01Z"}], "capital": {"nature": "parts_sociales", "nombre_titres": 3000, "valeur_nominale_totale": 3000, "devise": "EUR", "detenu_par_personnes_physiques_pct": 49}, "licence": "Uzņēmumu reģistrs / VID, data.gov.lv, CC0 1.0"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
