INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('e5db0416-4c48-51bc-ac07-290af7e80689','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/EE/{registrikood}/evenements','GET',0.02,true,true,'Estonian registry rulings (määrused) — striking-off and dissolution warnings, fines, entries. Estonian registry rulings (määrused) — early-warning credit-risk signal from the e-Business Register open data (RIK, CC BY 4.0, daily national photo): entries, remedy orders, striking-off/dissolution WARNINGS, annual-report fines, dated. alerte flags a CLOSED type list (rest in types_non_qualifies); nombre_alertes excludes only rulings explicitly resolved (etat_code=L) — every other state (J, K, unseen codes) still counts. A still-registered entity with no ruling gets a dated positive answer.','{"type": "object", "properties": {"registrikood": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Estonian registry code", "x-parameter-location": "path"}}, "required": ["registrikood"]}'::jsonb,'{"type":"object"}','{"pays": "EE", "id_national": "10119794", "aucune_ordonnance": false, "nombre_alertes": 2, "types_non_qualifies": [{"code": "K1", "libelle": "Kanne"}], "evenements": [{"numero": "Ä 30001556 / M1", "date_ordonnance": "2021-02-03", "date_inscription": null, "delai_supplementaire": "2021-08-03", "type_code": "X2", "type_libelle": "Hoiatusmäärus registrist kustutamiseks: majandusaasta aruanne esitamata", "etat_code": "J", "etat_libelle": "Jõustunud", "alerte": true}], "photo_le": "2026-07-29", "source": "e-äriregister (Registre du commerce estonien) — open data avaandmed.ariregister.rik.ee (aruannete elemendid, määrused), RIK, licence CC BY 4.0"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CON