INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('f886611d-cbe2-5200-8e6e-d07bea63bce1','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/SE/{orgnr}/comptes','GET',0.03,true,true,'Swedish annual accounts (Bolagsverket iXBRL filings) — every digitally filed fiscal year in one call. Swedish company annual accounts and financial statements decoded from the iXBRL filings Bolagsverket publishes for free (EU high-value datasets since 3 Feb 2025). Query: /v1/eu/entreprise/SE/5560401977/comptes (10-digit organisationsnummer). EVERY digitally filed fiscal year: revenue, operating and net result, balance sheet (total assets, equity, debts), average employees and prior-year column as filed. Digital filing is optional in Sweden (~63% of reports): absence never means no accounts.','{"type": "object", "properties": {"orgnr": {"type": "string", "pattern": "^\\d{6}-?\\d{4}$", "maxLength": 500, "minLength": 1, "description": "10-digit Swedish organisationsnummer, with or without hyphen", "x-parameter-location": "path"}}, "required": ["orgnr"]}'::jsonb,'{"type":"object"}','{"pays": "SE", "id_national": "5560401977", "nombre_exercices": 4, "exercices": [{"date_cloture": "2025-12-31", "denomination": "Research Premises Scandinavia Aktiebolag", "devise": "SEK", "chiffre_affaires": 891571, "resultat_net": 15721, "total_actif": 351010, "capitaux_propres": 263724}], "source": "Bolagsverket — värdefulla datamängder (bulkfil des organisations et rapports annuels iXBRL), vardefulla-datamangder.bolagsverket.se"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('093058bb-2d3c-5492-921c-02646651e56a','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/SE/{orgnr}/evenements','GET',0.02,true,true,'Swedish company registry events (Bolagsverket weekly national file). Swedish company registry events from Bolagsverket''s official weekly national file (free EU high-value dataset) — credit risk signals: incorporation, ONGOING bankruptcy (konkurs), liquidation, company reconstruction, composition proceedings, merger or division, and deregistration with coded reason and date. Query: /v1/eu/entreprise/SE/5560012402/evenements (10-digit organisationsnummer). A registered company with no proceeding returns an explicit positive answer — the register is authoritative.','{"type": "object", "properties": {"orgnr": {"type": "string", "pattern": "^\\d{6}-?\\d{4}$", "maxLength": 500, "minLength": 1, "description": "10-digit Swedish organisationsnummer, with or without hyphen", "x-parameter-location": "path"}}, "required": ["orgnr"]}'::jsonb,'{"type":"object"}','{"pays": "SE", "id_national": "5560012402", "nombre_evenements": 1, "evenements": [{"type": "immatriculation", "code": "REG", "libelle": "immatriculation au registre", "date": "1897-09-20", "en_cours": false}], "procedure_en_cours": false, "radiee": false, "source": "Bolagsverket — värdefulla datamängder (bulkfil des organisations et rapports annuels iXBRL), vardefulla-datamangder.bolagsverket.se", "data_freshness": "photo nationale HEBDOMADAIRE de Bolagsverket pré-ingérée (republiée le lundi)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCL