INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7965ffe9-1046-59ae-8243-3a9c13a9cca5','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/DK/{cvr}/dirigeants','GET',0.01,true,true,'Danish company officers (CVR, Erhvervsstyrelsen, live) — management bodies and mandates. Danish company officers and directors (deltagere) live from the official CVR register (Erhvervsstyrelsen system-to-system) by CVR number — governance and KYB: executive board (Direktion), board members (Bestyrelse) incl. deputies, election method, fully liable I/S or K/S partners and auditors — name, body, role, mandate dates. Active mandates by default; inclure_anciens=true adds ended ones where founders (stiftere) normally are. GDPR minimisation: never an address, never a personal identifier.','{"type": "object", "properties": {"cvr": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Danish CVR number", "x-parameter-location": "path"}, "inclure_anciens": {"type": "string", "enum": ["true"], "maxLength": 500, "minLength": 1, "description": "Also return ended mandates, each with its end date", "x-parameter-location": "query"}}, "required": ["cvr"]}'::jsonb,'{"type":"object"}','{"pays": "DK", "id_national": "24256790", "denomination": "NOVO NORDISK A/S", "statut": "NORMAL", "nombre_mandats_en_cours": 20, "nombre_anciens_mandats": 9, "tronque": false, "dirigeants": [{"nom": "DELOITTE STATSAUTORISERET REVISIONSPARTNERSELSKAB", "type": "entite", "organe": "Revision", "organe_type": "REVISION", "fonction": "REVISION", "depuis": "2021-03-25", "jusqu_au": null, "en_cours": true, "mode_election": null, "cvr": "33963556"}], "source": "CVR — Erhvervsstyrelsen (Danish Business Authority), accès system-à-système distribution.virk.dk", "data_freshness": "CVR temps réel (cache 24 h)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7ff8dc77-02a5-5feb-9911-ea6a58c89114','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/CZ/{ico}/insolvabilite','GET',0.02,true,true,'Czech company insolvency record (ISIR — Insolvenční rejstřík, since 2008). Czech company insolvency from ISIR, the official insolvency register of Czechia, since 2008. Query: /v1/eu/entreprise/CZ/45274649/insolvabilite (8-digit IČO). Every proceeding — bankruptcy (konkurs), reorganisation (reorganizace): case number, court, status, dates, its 100 most recent events with document links. Publication is compulsory by law: no proceeding is an explicit positive answer. LEGAL PERSONS ONLY: a natural person''s IČO (sole trader — most Czech IČOs) is refused, never cleared.','{"type": "object", "properties": {"ico": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Czech IČO", "x-parameter-location": "path"}}, "required": ["ico"]}'::jsonb,'{"type":"object"}','{"pays": "CZ", "id_national": "49193881", "aucune_procedure": false, "procedures": [{"affaire": "INS 9/2008", "debiteur": "ZRK Čekanice s.r.o.  v likvidaci", "tribunal": "KSZPCPM", "etat": "VYRIZENA", "ouverture": "2008-01-03T14:15:17Z", "nombre_evenements": 9, "evenements_tronques": false, "evenements": [{"id": 1946, "publie_le": "2008-01-14T09:36:31Z", "type": 83, "description": "Usnesení o zamítnutí insolvenčního návrhu pro nedostatek majetku dlužníka", "etat": "VYRIZENA"}]}], "collecte_le": "2026-07-31", "source": "ISIR — Insolvenční rejstřík (Ministerstvo spravedlnosti ČR), web service public isir.justice.cz"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('2da70359-577e-5b0c-ba5f-91552c7604b8','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/PL/{krs}/evenements','GET',0.02,true,true,'Polish company registry events (KRS daily bulletin) — liquidation, bankruptcy, filings, changes. Polish company registry EVENTS from the official KRS daily bulletin (Ministry of Justice) — company monitoring for Poland. Query: /v1/eu/entreprise/PL/0000006865/evenements (KRS number). Liquidation, bankruptcy, restructuring, mergers, suspension/resumption, dissolution, tax arrears, enforcement, accounts filings, name/seat/capital changes, strike-off — each typed from a CLOSED list, dated, traced to its section, in a gap-free window. GDPR by design: no officer, no PESEL, no register free text.','{"type": "object", "properties": {"krs": {"type": "string", "pattern": "^\\d{10}$", "maxLength": 500, "minLength": 1, "description": "10-digit KRS number, leading zeros included", "x-parameter-location": "path"}}, "required": ["krs"]}'::jsonb,'{"type":"object"}','{"pays": "PL", "krs": "0000006865", "observation": {"depuis": "2026-07-01", "jusqu_au": "2026-07-28"}, "aucun_evenement": true, "nombre_evenements": 0, "evenements": [], "derniere_observation": null, "existence": {"verifiee": false, "explication": "Existence NON vérifiée : cette route ne lit que les journées du Biuletyn, et ce numéro n''y a jamais figuré pendant la fenêtre. `aucun_evenement: true` signifie « aucun changement publié pendant la fenêtre » — PAS « société existante restée calme » : un numéro inexistant donne exactement la même réponse. Pour trancher l''existence, appeler la fiche d''identité LIVE (elle rend 404 si le KRS n''existe pas). / Existence NOT verified: this route only reads the daily bulletin and this number never appeared in it during the window; an unknown number yields the very same answer. Use the live identity endpoint to settle existence (it returns 404 when the KRS does not exist).", "route_identite": "/v1/eu/entreprise/PL/0000006865"}, "retard_jours": 1, "source": "Krajowy Rejestr Sądowy (KRS) — Ministerstwo Sprawiedliwości, API ouverte api-krs.ms.gov.pl (Biuletyn quotidien + OdpisAktualny)", "licence": "Données publiques du Krajowy Rejestr Sądowy (Ministerstwo Sprawiedliwości, api-krs.ms.gov.pl), réutilisation libre"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('527bd5a4-09f8-5d8f-98e9-10fa7e9e4bf9','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/{pays}/{id}/comptes','GET',0.01,true,true,'Company filings list — Belgium (NBB CBSO) and Finland (PRH XBRL filings). BE: every published annual-account deposit with its reference and filing metadata as published by the NBB (Authentic Data). FI: the fiscal years available from PRH XBRL filings (empty filings filtered out — every listed year carries figures). FI stock refreshed WEEKLY. Plus score_defaillance (statut non_evaluable + closed-list reasons: no default-risk score outside France — see GET /v1/lecture).','{"type": "object", "properties": {"pays": {"type": "string", "pattern": "^([Bb][Ee]|[Ff][Ii])$", "maxLength": 500, "minLength": 1, "description": "BE (Belgian annual accounts) or FI (Finnish XBRL-filed annual accounts, ~5% coverage)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^(\\d{10}|\\d{7}-\\d)$", "maxLength": 500, "minLength": 1, "description": "BE: 10-digit enterprise number (KBO/BCE). FI: Business ID NNNNNNN-N (e.g. 0103396-3)", "x-parameter-location": "path"}}, "required": ["pays", "id"]}'::jsonb,'{"type":"object"}','{"pays": "BE", "id_national": "0400378485", "nombre_depots": 93, "depots": [{"reference": "2025-00539072", "detail": {"DepositDate": "2025-10-07", "ExerciseDates": {"startDate": "2024-04-01", "endDate": "2025-03-31"}, "Currency": "EUR", "EnterpriseName": "Colruyt Group", "AccountingDataURL": "https://ws.cbso.nbb.be/authentic/deposit/2025-00539072/accountingData"}}], "telechargement": "GET /v1/eu/entreprise/BE/{id}/comptes/{reference}", "source": "Banque nationale de Belgique — Centrale des bilans (CBSO), webservice Authentic Data", "disclaimer": "Comptes annuels tels que déposés et publiés par la Centrale des bilans de la BNB (dépôts immuables)", "data_freshness": "BNB CBSO temps réel, liste en cache 24 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('faabb85b-d6d3-5b65-8bbd-7c3780876aa1','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/DK/{id}/comptes','GET',0.01,true,true,'Danish company filings list — fiscal years decoded from XBRL annual reports (Erhvervsstyrelsen). The fiscal years whose XBRL annual report (virk.dk publication index) has been decoded: closing dates, period, entity name, currency. Danish-taxonomy (fsa) filings only — IFRS/ESEF-only groups are not decoded; absence does not mean no accounts exist.','{"type": "object", "properties": {"id": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Danish CVR number", "x-parameter-location": "path"}}, "required": ["id"]}'::jsonb,'{"type":"object"}','{"pays": "DK", "id_national": "41235292", "nombre_depots": 1, "depots": [{"date_cloture": "2025-12-31", "debut_exercice": "2025-01-01", "fin_exercice": "2025-12-31", "denomination": "Nielsen Media Denmark ApS", "devise": "DKK"}], "telechargement": "GET /v1/eu/entreprise/DK/{cvr}/comptes/{date_cloture} — l''exercice décodé ($0.05)", "source": "Erhvervsstyrelsen (Danish Business Authority) — offentliggørelser, distribution.virk.dk", "disclaimer": "Extraits décodés des dépôts XBRL danois en taxonomie « regnskab » (fsa) tels que publiés", "data_freshness": "stock XBRL pré-ingéré depuis l''index officiel virk.dk"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7af57a46-c7f8-5333-8b35-4e5082baea7c','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/SK/{ico}/comptes','GET',0.01,true,true,'Slovak company filings list — fiscal years decoded from structured statements (RÚZ, CC0). The fiscal years whose STRUCTURED financial statements at the Register účtovných závierok have been decoded: closing date, period, filing type, form model, statutory vs consolidated scope, official document link. A single closing date MAY appear more than once — an ordinary (Riadna) and an extraordinary (Mimoriadna) filing are two distinct filings, never merged; each entry carries the `type_depot` and `perimetre` that select it on the detail endpoint. PDF-only filings (every IFRS group among them) carry no structured data and are absent; absence does not mean no accounts exist. Sole traders are not served (GDPR minimisation).','{"type": "object", "properties": {"ico": {"type": "string", "pattern": "^\\d{8}$", "maxLength": 500, "minLength": 1, "description": "8-digit Slovak IČO", "x-parameter-location": "path"}}, "required": ["ico"]}'::jsonb,'{"type":"object"}','{"pays": "SK", "id_national": "36417475", "nombre_depots": 2, "depots": [{"date_cloture": "2025-12-31", "debut_exercice": "2025-01-01", "denomination": "PODLAHY RK, s. r. o.", "perimetre": "statutaire", "type_depot": "Riadna", "modele": "Úč POD", "nb_postes": 16, "source_url": "https://www.registeruz.sk/cruz-public/domain/financialreport/show/7073209"}], "telechargement": "GET /v1/eu/entreprise/SK/{ico}/comptes/{date_cloture} ($0.03)", "source": "Register účtovných závierok (RÚZ) — Ministerstvo financií SR, registeruz.sk, open API publique", "licence": "CC0 (RÚZ Open API, Ministerstvo financií SR)", "disclaimer": "Postes clés normalisés extraits des états financiers STRUCTURÉS déposés au RÚZ"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('b874b4f8-a566-547c-8056-78240513bfae','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/GB/{company_number}/comptes','GET',0.01,true,true,'UK company accounts filings list — financial years decoded from iXBRL accounts (Companies House). The balance-sheet dates whose iXBRL annual accounts have been decoded, with period, entity name, currency, accounting framework and accounts type. Electronically filed accounts only (~75% of UK filings), depth accumulated since 2026-07 (the daily source file is retained 60 days) — absence does not mean no accounts exist. Open Government Licence v3.0.','{"type": "object", "properties": {"company_number": {"type": "string", "pattern": "^([0-9]{8}|[A-Za-z]{2}[0-9]{6}|[A-Za-z][0-9]{7})$", "maxLength": 500, "minLength": 1, "description": "Companies House company number, 8 characters incl. leading zeros (00095407, SC123456, OC427207)", "x-parameter-location": "path"}}, "required": ["company_number"]}'::jsonb,'{"type":"object"}','{"pays": "GB", "id_national": "00095407", "nombre_depots": 1, "depots": [{"date_cloture": "2025-12-31", "debut_exercice": "2025-01-01", "denomination": "COSSART,GORDON AND CO.LIMITED", "devise": "GBP", "referentiel": "Micro-entities", "type_comptes": "FullAccounts", "nb_postes_decodes": 14, "nb_postes_courant": 7}], "telechargement": "GET /v1/eu/entreprise/GB/{company_number}/comptes/{date_cloture}", "source": "Companies House — Free Accounts Data Product (download.companieshouse.gov.uk)", "licence": "Contains public sector information licensed under the Open Government Licence v3.0 (Companies House)", "disclaimer": "Postes décodés des comptes annuels déposés en iXBRL à Companies House"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('8004b762-7c45-57ec-840e-457b072e98b4','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/intelligence/{siren}','GET',1.0,true,true,'Company intelligence report — every block cross-referenced, closed-list signals, rule-based verdict. Identity, officers, financials with 3-year trend, sector positioning (NAF benchmarks), failure-risk score, BODACC alerts, sanctions screening (6 lists, company + officers), procurement (French DECP + EU TED), IP, cached capital structure, industrial-risk synthesis (Seveso/ICPE), AMF PSAN/SGP registers, HATVP lobbying summary, live VIES VAT check — plus closed-list signals traced to their register source, a deterministic verdict (solide/correct/fragile/critique/indeterminable) with `synthese.motifs_verdict` (closed-list codes that decided it) and `synthese.verdict_plafonne_par` (name-match doubts that capped a would-be « solide » at « correct » — when non-empty, read « correct » as « correct subject to verification »; v1.6), `synthese.reserves` / `portee` / `confiance_financiere` / `par_domaine` (v1.7: closed-list reading caveats, scope, score confidence band and a ten-domain projection of blocks already served — the verdict word is unchanged), and strengths/vigilance points. Ed25519-signed (v1.2). Carries the common `provenance[]` envelope (states and reading rules: GET /v1/lecture, free). AMF blacklist (since 2026-09-04): `risques.alertes_amf` serves the matches with score, level and qualification from the shared screening analyser; the vigilance signal `correspondance_liste_noire_amf` is raised only when a match weighs in the concordance table, otherwise the informative `rapprochement_liste_noire_amf_partiel` is emitted and no vigilance point is added. Since 2026-09-06 a failure score in the « vigilance » band raises `score_defaillance_vigilance` — a vigilance point and the verdict motif (negative, not damning: caps at « correct »), so a « correct » decided by the score alone is never served with an empty `points_vigilance`; a « correct » with no vigilance point now reads « solid not granted, see motifs_verdict ».','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "type_rapport": "intelligence", "version_rapport": "1.4", "identite": {"denomination": "DANONE", "categorie_entreprise": "GE", "activite_principale": "70.10Z", "etat_administratif": "actif"}, "tva_vies": {"statut": "valide"}, "risques": {"score_defaillance": {"score_risque": 22, "classe": "sain", "risque_12m": "faible"}}, "signaux": [{"signal": "propriete_industrielle_presente", "source": "bases PI INPI", "detail": "112 titre(s)"}], "synthese": {"verdict_global": "solide", "points_forts": ["anciennete_etablie"], "points_vigilance": []}, "score_completude": 100, "blocs_manquants": []}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('f37dd7b3-fe33-5fce-a2c2-745624108be0','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/documents','GET',0.02,true,true,'List official documents filed at the INPI RNE registry. Legal deeds (actes: statutes, general-meeting minutes...) and filed annual accounts (bilans), each with document ID, label, filing date. Only documents the registry marks as public. Use the ID with /v1/documents/{type}/{id} to download the PDF.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "actes": [{"id": "6a33ae8b0397b4bf6e0f5118", "type": "actes", "libelle": "Copie des statuts mis à jour", "date_depot": "2026-06-16", "nom_document": "Statuts_Danone_26_mai_2026_signes_2"}], "bilans": [{"id": "6a33a929f9e4b401ad07b51a", "type": "bilans", "libelle": null, "date_depot": "2026-05-27", "date_cloture": "2025-12-31", "nom_document": "CA_552032534_7501_K00245359617_2025_K"}], "total": 208, "consulte_le": "2026-07-29T07:28:49.560Z", "telechargement": "GET /v1/documents/{type}/{id} — type = actes | bilans, id = champ `id` ci-dessous ($0.10, PDF)", "source": "INPI — Registre national des entreprises (RNE), documents tels que déposés", "data_freshness": "INPI RNE temps réel, liste en cache 24 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('b1210294-d6d4-5a75-83f5-6ad443112bca','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/prospection','GET',0.02,true,true,'Multi-criteria prospecting over the full registry (100 active companies per paid page). Up to 100 active companies (SIREN, name, NAF, legal form, workforce bracket, creation date, head-office postal code/city), stable SIREN order, page_suivante flag.','{"type": "object", "properties": {"naf": {"type": "string", "maxLength": 500, "minLength": 1, "description": "NAF/APE code or prefix (62, 62.01, 62.01Z)", "x-parameter-location": "query"}, "departement": {"type": "string", "maxLength": 500, "minLength": 1, "description": "French departement (75, 2A, 971…) — exclusive with code_postal", "x-parameter-location": "query"}, "code_postal": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Postal-code prefix (2 to 5 digits)", "x-parameter-location": "query"}, "forme_juridique": {"type": "string", "maxLength": 500, "minLength": 1, "description": "INSEE legal-category prefix (e.g. 54, 5499)", "x-parameter-location": "query"}, "effectif_min": {"type": "integer", "description": "Minimum workforce (mapped to INSEE brackets)", "x-parameter-location": "query"}, "effectif_max": {"type": "integer", "description": "effectif_max", "x-parameter-location": "query"}, "age_min": {"type": "integer", "description": "Minimum company age in years", "x-parameter-location": "query"}, "age_max": {"type": "integer", "description": "age_max", "x-parameter-location": "query"}, "rge": {"type": "boolean", "description": "true = active RGE certification", "x-parameter-location": "query"}, "egapro_min": {"type": "integer", "description": "Minimum gender-equality index (0-100)", "x-parameter-location": "query"}, "page": {"type": "integer", "minimum": 1, "maximum": 100, "description": "Page number — each page is one payment", "x-parameter-location": "query"}}, "required": []}'::jsonb,'{"type":"object"}','{"criteres": {"naf": "62.01Z", "departement": "75", "page": 1}, "nombre_resultats": 100, "page": 1, "page_suivante": true, "resultats": [{"siren": "100000348", "denomination": "LES EDITIONS DIGITALES", "activite_principale": "62.01Z", "forme_juridique": "5710", "tranche_effectif_salarie": "NN", "date_creation": "2026-01-15", "code_postal_siege": "75011", "commune_siege": "PARIS"}]}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('a6a6d230-2880-5b6f-8601-ec7fb9cbbc01','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/sante','GET',0.15,true,true,'Business-health risk read-out (FR + EN, closed grid, official data only). Risk read-out from official data: `synthese` (resume FR + resume_en, strengths, warning signs, missing data, verdict, activity trend, confidence level), `grille` (the reconciled evaluation grid, machine-readable codes) and `divergences_modele` (where deterministic guards overruled the model). A model only picks values from closed lists: no free text, no name and no figure of its own. WHAT TO EXPECT ON THIN FILES: entities that file no annual accounts — non-profits, sole traders, companies under a year old, ceased companies — return `verdict: "non_concluant"` with most grid fields set to `non_evaluable`; the prose then states explicitly that no accounts are available and whether that is normal at this age, and a ceased company is flagged with the `entreprise_administrativement_fermee` warning. Measured on a random sample of 47 SIREN: half of them are such files. Includes model, prompt version and cache status. Cached 7 days.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "synthese": {"points_forts": ["Résultats nets positifs récurrents"], "points_vigilance": ["Ratios incohérents dans la source officielle"], "donnees_manquantes": ["Structure du passif"], "verdict": "sous_reserve", "tendance_activite": "croissance", "niveau_confiance": "faible"}, "grille": {"verdict": "sous_reserve", "ca_tendance": "croissance_forte", "ca_regularite": "irreguliere", "rentabilite_niveau": "forte", "rentabilite_tendance": "volatile", "endettement_niveau": "eleve", "endettement_tendance": "alourdissement", "autonomie_financiere": "correcte", "liquidite": "echelle_non_etablie", "capacite_remboursement": "correcte", "bfr_exploitation": "atypique_negatif", "structure_synthese": "equilibree", "points_forts": ["resultats_nets_positifs_recurrents"], "points_vigilance": ["ratios_incoherents"], "confiance_niveau": "faible", "confiance_motifs": ["incoherences_detectees"], "donnees_manquantes": ["structure_du_passif"]}, "divergences_modele": ["correspondance de criblage : verdict contraste -> sous_reserve"], "modele": "claude-sonnet-5", "version_prompt": "sante-v2", "genere_le": "2026-08-11T07:51:02.474Z", "donnees": {"score_completude": 100, "data_freshness": "identité : stock Sirene mensuel (2026-07-01)"}, "depuis_cache": true}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('8439c954-b24a-54d9-9e81-5a18a7c6f77a','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/score/defaillance/{siren}','GET',0.1,true,true,'Company default-risk score (transparent scorecard + BODACC override). Credit risk scoring for a French company: a default-risk score (0-100) at ~12 months from a transparent scorecard — filed financial ratios (structure, profitability, liquidity, net cash, debt service, trend), company age, and a hard BODACC override (open insolvency/liquidation, or closure for insufficiency of assets). Returns the score, a qualitative band, every component with its threshold, and a confidence level. Decision-support indicator — NOT a solvency opinion or credit rating.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "score_risque": 22, "classe": "sain", "risque_12m": "faible", "composantes": [{"axe": "liquidite", "indicateur": "ratio_liquidite_%", "valeur": 7.093, "seuil": "<80/<100", "points": 12}, {"axe": "dette", "indicateur": "capacite_remboursement_annees", "valeur": 19.515, "seuil": "<0/>7/>4", "points": 10}], "exercice_reference": "2024-12-31", "confiance": "moyenne", "version_modele": "defaillance-v1.8", "avertissement_perimetre": "Comptes SOCIAUX seuls : la santé du GROUPE n''est pas mesurée ; sur une tête de groupe, dette et liquidité peuvent être structurelles. Confiance plafonnée à « moyenne ». / Standalone STATUTORY accounts: GROUP health is not measured; on a group parent, debt and liquidity may be structural. Confidence capped at medium.", "signaux_bodacc": {"procedure_collective": false, "liquidation_judiciaire": false, "cloture_insuffisance_actif": false}, "data_freshness": "identité stock Sirene (2026-07-01) + ratios financiers + BODACC temps réel"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('afce3290-dadb-539c-bf7a-3cde630963ab','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/secteur/{code_naf}/benchmarks','GET',0.05,true,true,'Sector benchmarks by NAF activity code (medians vs peers). Sector benchmarks and sector statistics for a French NAF activity code (any level: division, groupe, classe, sous-classe): number of active companies, median company age (with quartiles), workforce-bracket distribution, and — when at least 5 companies file public accounts — median revenue, EBITDA margin, pre-tax result and debt ratio. Peer comparison in one call: place a company against its peers. Aggregates only, no personal data; sectors with fewer than 5 companies are excluded.','{"type": "object", "properties": {"code_naf": {"type": "string", "pattern": "^\\d{2}(\\.\\d{0,2}[A-Z]?)?$", "maxLength": 500, "minLength": 1, "description": "NAF code, any level: division (68), groupe (68.2), classe (68.20), sous-classe (68.20B)", "x-parameter-location": "path"}}, "required": ["code_naf"]}'::jsonb,'{"type":"object"}','{"code_naf": "62.01Z", "niveau": "sous-classe", "effectif_entreprises": {"actives_diffusibles": 98868}, "age_annees": {"mediane": 4, "q1": 1, "q3": 11}, "effectifs_salaries": {"repartition": {"NN": 88097}, "repartition_libelles": {"NN": "non renseigné"}}, "finances": {"entreprises_avec_comptes": 8950, "marge_ebe_pct": {"mediane": 7.197}, "rcai_sur_ca_pct": {"mediane": 3.989}, "taux_endettement": {"mediane": 3.348}}, "source": "INSEE Sirene (Licence Ouverte Etalab 2.0) et ratios financiers INPI / Banque de France (Licence Ouverte 2.0)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('d0fcde1b-070a-5f8b-9b3f-c41ef23a6ad7','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/capital','GET',0.35,true,true,'Capital / ownership extracted by AI from public INPI articles of association. Ownership and share capital structure of a French company from the official INPI registry: AI extraction of the latest PUBLIC articles of association filed at INPI — share capital amount, legal form, shareholders (name, role, birth YEAR, ownership %), notable clauses, with a confidence level and the source document reference. Due diligence from public filed deeds — NOT a beneficial-ownership register (RBE) and not a beneficial-owner identification. Immutable document: extracted once, cached.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "modele": "claude-sonnet-5", "capital": {"montant_capital_eur": 170739060, "forme_juridique": "Société anonyme", "associes": [], "clauses_notables": ["droit_de_vote_double"], "confiance": "faible"}, "version_prompt": "capital-v2", "document_source": {"id": "6a33ae8b0397b4bf6e0f5118", "nom": "Statuts_Danone_26_mai_2026_signes_2", "type": "actes", "date_depot": "2026-06-16"}, "depuis_cache": true, "source": "INPI — actes/statuts publics déposés au registre national des entreprises (RNE)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('1c68cf9f-5de4-5317-9b14-b5dff835da9d','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/pi','GET',0.03,true,true,'Industrial-property portfolio (trademarks, patents, designs) from INPI open data. Intellectual property portfolio of a French company from official INPI open data: patents, trademarks and designs — counts plus items with number, title/label, status, ISO dates (trademark filing/registration/expiry, patent publication) and classification (Nice/CIB/Locarno). Designs: one line per filing. An R&D / brand-value signal for due diligence. Trademarks and designs are most-recent-first; patents are NOT sorted upstream (liste_ordre). Inventor names are never returned.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "marques": {"nombre": 88, "liste": [{"numero": "4789796", "libelle": "THE ONE HOME", "statut": "Marque enregistrée", "date": "2021-07-31", "date_nature": "depot", "date_enregistrement": "2021-12-24", "date_expiration": "2031-07-31", "classification": "41, 44"}], "liste_tronquee": true, "nombre_unite": "titres", "liste_ordre": "date_decroissante"}, "brevets": {"nombre": 12, "liste": [{"numero": "FR2728873A1", "libelle": "EMBALLAGE EN FILM DE MATERIAU SOUPLE ET SON PROCEDE DE FABRICATION", "date": "1996-07-05", "date_nature": "publication", "classification": "B65D 65/32, B65D 75/58"}], "liste_tronquee": false, "nombre_unite": "titres", "liste_ordre": "amont_non_trie"}, "dessins_modeles": {"nombre": 3, "liste": [{"numero": "054041", "libelle": "Ornementation de supports de communication", "date": "2005-08-19", "date_nature": "depot", "classification": "2003"}], "liste_tronquee": false, "nombre_unite": "depots", "liste_ordre": "date_decroissante"}, "source": "INPI — bases ouvertes de propriété industrielle (marques, brevets, dessins & modèles)", "data_freshness": "INPI PI open data (marques/brevets hebdo, D&M bimensuel), cache 24 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('3dac8f55-ba3b-5712-be94-c6d01f22ebcc','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/changements','GET',0.01,true,true,'New BODACC announcements since a date (poll-mode surveillance). Company changes monitoring for a French company: the new official BODACC gazette announcements published SINCE a given date (?depuis=YYYY-MM-DD) — the poll endpoint for watchlist and portfolio surveillance. Returns the new announcements (insolvency, deregistration, sales, filings, changes) in reverse-chronological order. Note: detects new BODACC publications, not field-level edits of the Sirene/RNE profile (the monthly stock keeps no history).','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}, "depuis": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$", "maxLength": 500, "minLength": 1, "description": "List announcements published on or after this date (YYYY-MM-DD)", "x-parameter-location": "query"}}, "required": ["siren", "depuis"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "denomination": "DANONE", "depuis": "2020-01-01", "nouveaux_evenements_bodacc": {"nombre": 41, "nombre_total": 41, "tronque": false, "annonces": [{"id": "B202601212014", "date_parution": "2026-06-28", "type_avis": "Avis initial", "tribunal": "Greffe du Tribunal des Activités Economiques de Paris", "jugement": null, "publication": "B", "famille": "Modifications diverses"}]}, "changements_fiche": {"disponible": false, "version_stock_courant": "2026-07-01"}, "source": "BODACC (DILA) via bodacc-datadila.opendatasoft.com, licence ouverte Etalab 2.0", "data_freshness": "BODACC (bulletin quotidien DILA), cache court ≤ 1 h par (siren, depuis)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('2578424c-2e7a-5fbe-af8a-cb8e7e57d4d6','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/facture/verifier','GET',0.02,true,true,'Invoice verification — cross-check the identifiers printed on a French invoice. Invoice verification for France — cross-check the identifiers PRINTED ON an invoice in one call: SIREN against the official registry (existence, active status, live), the VAT number on the invoice against the one computed from the SIREN AND live against VIES, the IBAN (ISO form, key digits, bank identified). Deterministic verdict coherent/incoherent/inverifiable, closed-list reasons. Flags a VAT that belongs to another company or a ceased supplier. Not a payee verification.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN printed on the invoice", "x-parameter-location": "query"}, "tva": {"type": "string", "maxLength": 20, "minLength": 1, "description": "VAT number printed on the invoice — cross-checked against the one computed from the SIREN AND live against VIES. At least one of tva/iban is required (400 otherwise)", "x-parameter-location": "query"}, "iban": {"type": "string", "maxLength": 40, "minLength": 1, "description": "IBAN printed on the invoice — ISO form + key digits + bank identification (never a holder-name check). At least one of tva/iban is required", "x-parameter-location": "query"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "etat_administratif": "actif", "controles": {"tva": {"fournie": "FR27552032534", "attendue_pour_ce_siren": "FR27552032534", "correspond_au_siren": true, "vies": {"statut": "valide"}}, "iban": {"valide": true, "exemple_de_documentation": true, "banque": {"identifiee": true}}}, "verdict": "coherent", "raisons": [{"code": "iban_exemple_documentation", "niveau": "information", "source": "IBAN publié comme EXEMPLE de documentation — bien formé ; existence du compte non contrôlée."}], "non_verifie": ["existence_du_compte", "nom_du_titulaire"], "source": "Composition Sirenic : INSEE Sirene (état, live), croisement TVA calculée (clé FR déterministe), VIES (Commission européenne, live), contrôle de forme IBAN + registres bancaires officiels", "disclaimer": "Croisement déterministe des identifiants affichés par une facture (raisons en liste fermée, tracées à leur source) — ni un avis de conformité fiscale, ni une Verification of Payee : le volet bancaire contrôle la FORME et identifie la banque, sans vérifier l''existence du compte ni le nom du titulaire — un IBAN valide mais substitué n''est pas détectable ici. / Deterministic cross-check of the identifiers printed on an invoice — neither tax advice nor a Verification of Payee: the bank leg checks FORM and identifies the bank; a valid-but-swapped IBAN cannot be detected here."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('d84b7e7a-9e8c-540c-9a56-b246c8c7fd7e','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/facturation/dossier','GET',0.03,true,true,'Verify a supplier before payment — France (e-invoicing mandate, 1 September 2026). Invoice verification and supplier verification — verify supplier before payment in France, the invoicing pack of the e-invoicing mandate France September 2026 (all VAT-liable companies must receive): legal identity, obligation dates, intra-EU VAT number checked LIVE against VIES, IBAN form + key check, bank identified, deterministic pret_a_facturer verdict, closed-list reasons. Not a payee verification: no holder name, no account existence check. A VIES outage never yields a false invalid.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN of the invoice recipient", "x-parameter-location": "query"}, "iban": {"type": "string", "maxLength": 40, "minLength": 1, "description": "Optional supplier IBAN — form check (structure + key) and bank identification before the first payment", "x-parameter-location": "query"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "destinataire": {"destinataire": {"denomination": "DANONE", "etat_administratif": "actif"}}, "tva_vies": {"numero": "FR27552032534", "statut": "valide"}, "banque": {"iban_normalise": "FR1420041010050500013M02606", "valide": true, "exemple_de_documentation": true, "banque": {"nom": "La Banque Postale", "bic": "PSSTFRPPXXX"}, "verification_titulaire": "non_disponible"}, "verdict": {"pret_a_facturer": true, "non_verifie": ["existence_du_compte", "nom_du_titulaire"], "raisons": [{"code": "iban_exemple_documentation", "niveau": "information", "source": "IBAN publié comme EXEMPLE de documentation — bien formé ; existence du compte non contrôlée."}]}, "source": "Composition Sirenic : préparation e-facturation (INSEE Sirene), VIES (Commission européenne, live), contrôle de forme IBAN + registres bancaires officiels", "disclaimer": "Aide à la décision déterministe (raisons en liste fermée, tracées à leur source) — ni un avis de conformité fiscale, ni une Verification of Payee : le volet bancaire contrôle la FORME et identifie la banque, sans vérifier l''existence du compte ni le nom du titulaire ; la TVA (VIES) et l''état Sirene, eux, sont vérifiés en direct. / Deterministic decision support — neither tax-compliance advice nor a Verification of Payee: the bank leg checks FORM (structure + key digits) and identifies the bank, without checking the account''s existence or the holder''s name; the VAT (VIES) and the Sirene registry status are checked live."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('6b2e4bd9-4c58-5c60-9658-2a8b1282d461','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/facturation-prep','GET',0.02,true,true,'Prepare an e-invoice for a French recipient (mandate of 1 September 2026). Supplier onboarding: PREPARE a compliant French e-invoice under the e-invoicing mandate France September 2026 (reception obligatory for every VAT-liable company; issuance phased GE/ETI 2026, SME 2027): legal name & form, status, computed intra-EU VAT number (with VIES pointer), establishments (SIRET) with addresses, NAF code, indicative obligation dates. Preparation only - Sirenic is not an accredited platform (PDP), never accesses the central directory and never issues or routes invoices.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated) of the invoice RECIPIENT", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "statut_diffusion": "totale", "destinataire": {"denomination": "DANONE", "nature_juridique": "5599", "etat_administratif": "actif", "activite_principale": "70.10Z", "categorie_entreprise": "GE"}, "tva": {"numero_intracommunautaire_calcule": "FR27552032534"}, "adressage": {"siege": {"siret": "55203253400703", "adresse": "59 RUE LA FAYETTE 75009 PARIS", "code_postal": "75009", "commune": "PARIS"}, "nombre_etablissements": 19, "etablissements": [{"siret": "55203253400703", "est_siege": true, "adresse": "59 RUE LA FAYETTE 75009 PARIS", "etat_administratif": "actif"}]}, "calendrier_reforme": {"reception_obligatoire_depuis": "2026-09-01", "emission_obligatoire_depuis": "2026-09-01", "base_calcul": "catégorie d''entreprise INSEE : GE"}, "avertissements": [], "data_freshness": "identité : stock Sirene mensuel (2026-07-01)", "disclaimer": "Données de préparation fournies à titre indicatif ; Sirenic n''émet, ne transmet ni ne route aucune facture, et ne confirme pas l''enregistrement du destinataire sur le PPF ou une PDP."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7d67e8ea-b562-5c6d-b8f2-3442e09db9d0','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/bodacc/recherche','GET',0.03,true,true,'Search BODACC legal announcements by criteria (family, date window, department). Search French BODACC legal announcements by CRITERIA, not by company: pick a family (insolvency proceedings, deregistrations, sales, incorporations, accounts filings, conciliation...), a date window and optionally a department. Answers questions like: which companies entered insolvency proceedings in department 59 this week? Up to 100 announcements, newest first, each with its SIREN, court, town and structured judgment. Sole traders are excluded (their name is personal data) and counted.','{"type": "object", "properties": {"famille": {"type": "string", "enum": ["dpc", "modification", "creation", "radiation", "collective", "vente", "immatriculation", "divers", "conciliation", "retablissement_professionnel"], "maxLength": 500, "minLength": 1, "description": "Announcement family (closed list — these are the upstream BODACC codes, not translations): `collective` = insolvency/collective proceedings, `dpc` = accounts filings (the largest family, 26M), `retablissement_professionnel` = professional recovery. Note that `retablissement_professionnel` targets SOLE TRADERS, so this endpoint serves almost nothing for it and reports them under `exclues_personnes_physiques`.", "x-parameter-location": "query"}, "depuis": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Start of the publication window (YYYY-MM-DD). Required: there is no unbounded search.", "x-parameter-location": "query"}, "jusqu_a": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Optional end of the window (YYYY-MM-DD). The window may not exceed 366 days.", "x-parameter-location": "query"}, "departement": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Optional French department code: 01-95, 2A, 2B, 971-978.", "x-parameter-location": "query"}}, "required": ["famille", "depuis"]}'::jsonb,'{"type":"object"}','{"criteres": {"famille": "collective", "depuis": "2026-08-04", "departement": "59"}, "annonces": [{"id": "A202601513770", "date_parution": "2026-08-11", "famille": "Procédures collectives", "type_avis": "Avis initial", "tribunal": "Greffe du Tribunal Judiciaire de Lille", "ville": "Tourcoing, Lille Cedex", "code_postal": "59200, 59009", "departement": "59", "departement_nom": "Nord", "siren": null, "jugement": {"nature": "Autre jugement et ordonnance", "date": "2026-07-09", "famille": "Extrait de jugement"}, "url_bodacc": "https://www.bodacc.fr/pages/annonces-commerciales-detail/?q.id=id:A202601513770"}, {"id": "A202601503905", "date_parution": "2026-08-09", "famille": "Procédures collectives", "type_avis": "Avis initial", "tribunal": "Greffe du Tribunal de Commerce de Douai", "ville": "Hornaing", "code_postal": "59171", "departement": "59", "departement_nom": "Nord", "siren": "907941801", "jugement": {"nature": "Jugement d''ouverture d''une procédure de redressement judiciaire", "date": "2026-08-04", "famille": "Jugement d''ouverture"}, "url_bodacc": "https://www.bodacc.fr/pages/annonces-commerciales-detail/?q.id=id:A202601503905"}], "total_servi": 56, "exclues_personnes_physiques": 8, "exclues_type_indetermine": 0, "tronque": false, "limite": 100, "consulte_le": "2026-08-11T22:19:24.289Z", "source": "BODACC (Bulletin officiel des annonces civiles et commerciales), DILA — via l''API Opendatasoft officielle, Licence Ouverte 2.0"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('53142145-d9ff-5c6b-ac6e-3752e65035be','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/dirigeant/recherche','GET',0.02,true,true,'Reverse director search by surname. Reverse search for company directors and officers in France: a people search by surname (?nom=) that lists the French companies where a person of that name holds or held an office, with each company SIREN, name and the person role — network mapping and due diligence on directors. Person data is limited to surname, first names, role and birth YEAR (French GDPR/INPI rules). Results are indicative: homonyms are not disambiguated and very common names are capped.','{"type": "object", "properties": {"nom": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Director surname — unsupported characters are stripped rather than rejected; 400 only when nothing searchable is left (1 to 100 characters once cleaned up).", "x-parameter-location": "query"}}, "required": ["nom"]}'::jsonb,'{"type":"object"}','{"nombre_resultats": 1, "tronque": false, "resultats": [{"siren": "314685454", "denomination": "AGACHE", "etat_administratif": "actif", "statut_diffusion": "totale", "correspondance_locale": true, "mandats": [{"type": "personne_physique", "nom": "ARNAULT", "prenoms": "BERNARD", "fonction": "Autre", "annee_de_naissance": "1949"}]}]}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7c5c3efb-c2d4-5139-967e-1902ca3fa231','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/risques-industriels','GET',0.01,true,true,'Industrial-risk profile: classified ICPE facilities, Seveso status, risk synthesis. Industrial risk and environment profile of a French company from the official ICPE register (Géorisques/DGPR): classified facilities with Seveso status (upper/lower tier), authorisation regime, activity state, IED flag, nomenclature rubrics and a risk synthesis per SIREN — an ESG and environmental compliance signal on hazardous sites operated by the company. A company with no classified facility returns level aucun (still 200) — the clean answer is the signal.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "095580841", "synthese": {"niveau_risque_max": "seveso_seuil_haut", "nb_installations": 6, "nb_en_exploitation": 6, "seveso_seuil_haut": 2, "seveso_seuil_bas": 0, "par_regime": {"autorisation": 2, "enregistrement": 4, "autres": 0}, "ied": 0, "priorite_nationale": 2}, "installations": [{"code_aiot": "0005207266", "raison_sociale": "TEREGA - Centre de stockage", "commune": "Lussagnet", "code_postal": "40270", "statut_seveso": "Seveso seuil haut", "regime": "Autorisation", "etat_activite": "En exploitation avec titre", "ied": false}], "source": "Géorisques — Ministère de la Transition écologique (DGPR), base des installations classées, Licence Ouverte / etalab-2.0", "data_freshness": "stock Géorisques mensuel (extrait 2026-07-23)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('a3c74772-965e-50bf-bced-b20e416fb76d','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/emploi','GET',0.02,true,true,'Hiring signals: actively hiring, posting volume, ROME families, pay-range share, Egapro index. Hiring signals for a French company, derived on demand from France Travail data (snapshot under 24 h, nothing stored): actively-hiring yes/no/unprovable, active-postings count (SIREN-keyed employer page when available, else strict name matching over known locations), top ROME occupation families, contract-type mix, share of postings displaying a pay amount - plus the Egapro gender-equality index and the INSEE workforce bracket. Aggregated signals only, never posting texts or recruiter contacts.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "095580841", "denomination": "TEREGA", "signaux_recrutement": {"recrute_activement": null, "annonces_actives": 0, "familles_rome": [], "methode": {"comptage": "correspondance_denomination", "zones": {"type": "departements", "interrogees": 5, "connues": 12}, "annonces_examinees": 1050, "couverture_complete": false}, "consulte_le": "2026-08-25T05:39:42.272Z"}, "index_egapro": [{"annee": 2025, "note": 93}], "effectif": {"tranche": "500 à 999 salariés", "annee": "2023"}}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('3ad4f40e-e34e-5540-a284-1861e91846ed','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/facturation/dossier','GET',0.03,true,true,'Verify a supplier before payment — Belgium & Poland (incl. the White List account check). European invoice verification and supplier verification for e-invoicing compliance in Belgium (mandate live since 1 Jan 2026) and Poland (KSeF): official registry identity, VAT check against VIES, Peppol reachability (BE), IBAN form + key check, bank identified and, in Poland, the official White List: is the IBAN DECLARED by the taxpayer? Paying an undeclared account over 15,000 PLN costs the buyer the VAT deduction and joint liability. Deterministic pret_a_facturer verdict, closed-list reasons.','{"type": "object", "properties": {"pays": {"type": "string", "enum": ["BE", "PL"], "maxLength": 500, "minLength": 1, "description": "Belgium or Poland (for France use /v1/facturation/dossier)", "x-parameter-location": "query"}, "id": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Belgian enterprise number or Polish NIP (10 digits)", "x-parameter-location": "query"}, "iban": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Payee IBAN — optional; form check (structure + key) plus bank identification, and in Poland it unlocks the White List account check", "x-parameter-location": "query"}}, "required": ["pays", "id"]}'::jsonb,'{"type":"object"}','{"pays": "BE", "id": "0403199702", "destinataire": {"denomination": "BNP Paribas Fortis", "etat": null}, "tva": {"numero": "BE0403199702", "statut": "valide"}, "peppol": {"joignable": true, "identifiant": "0208:0403199702", "nom_enregistre": "BNP Paribas Fortis NV", "documents": ["Invoice"], "accepte_facture_en16931": true}, "banque": null, "mandat": {"obligation": "facturation électronique structurée entre assujettis", "en_vigueur_depuis": "2026-01-01", "canal_par_defaut": "Peppol (art. 13ter, présomption réfragable)"}, "verdict": {"pret_a_facturer": true, "raisons": [{"code": "iban_non_fourni", "niveau": "information", "source": "Paramètre `iban` absent — contrôle bancaire non effectué."}]}, "source": "Banque-Carrefour des Entreprises (BCE/KBO), VIES (Commission européenne), annuaire Peppol, registres bancaires officiels."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('bdff2b8b-7f86-57ce-bb63-917fe763242e','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/entreprise/{pays}/{id}/transactions-dirigeants','GET',0.02,true,true,'Belgian and German insider dealing (FSMA / BaFin, Art. 19 MAR): issuer-level aggregate, nobody named. Director transactions and insider transactions at Belgian and German listed companies — managers transactions (directors'' dealings) under MAR Article 19, as notified to the FSMA and BaFin: are the company''s managers buying or selling? Issuer-level aggregate over a rolling 12 months — counts, gross buy and sell amounts, net flow, breakdown by declarer category, and the underlying notifications. BE: 10-digit enterprise number. DE: LEI or ISIN. No individual is ever named.','{"type": "object", "properties": {"pays": {"type": "string", "enum": ["BE", "DE"], "maxLength": 500, "minLength": 1, "description": "Belgium (FSMA) or Germany (BaFin)", "x-parameter-location": "path"}, "id": {"type": "string", "pattern": "^(\\d{10}|[0-9A-Z]{18}[0-9]{2}|[A-Z]{2}[0-9A-Z]{9}[0-9])$", "maxLength": 500, "minLength": 1, "description": "BE: 10-digit enterprise number. DE: LEI or ISIN — BaFin publishes no register number.", "x-parameter-location": "path"}, "depuis": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$", "maxLength": 500, "minLength": 1, "description": "Start date (default: rolling 12 months)", "x-parameter-location": "query"}}, "required": ["pays", "id"]}'::jsonb,'{"type":"object"}','{"pays": "BE", "denomination": "UMICORE", "synthese": {"nb_notifications": 2, "nb_achats": 2, "nb_ventes": 0, "nb_autres": 0, "montant_achats_eur": 9765, "montant_ventes_eur": 0, "montant_net_eur": 9765, "nb_notifications_montant_hors_eur": 0, "nb_declarants_distincts": 2, "date_derniere_notification": "2026-08-06"}, "note_montants": null, "par_categorie_declarant": null, "ventilation_masquee": "Moins de 3 déclarants distincts sur la période : la ventilation par catégorie est masquée (y compris dans le détail des notifications), elle désignerait une personne identifiable. Les transactions et leurs montants restent servis.", "notifications": [{"reference_source": "621888", "date_publication": "2026-08-06", "date_transaction": "2026-08-05", "type_transaction": "acquisition", "lieu": "Off exchange", "quantite": 12500, "montant": 0, "devise": "EUR", "categorie_declarant": null}], "source": "FSMA — Transactions de dirigeants (art. 19 MAR), licence CC BY 4.0 ; identifiants d''entreprise résolus via GLEIF."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('d8d62bb0-91c3-501c-bef3-335adaaa9f6f','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/agrements','GET',0.02,true,true,'Regulatory authorisations: payment/e-money (EBA), insurance (EIOPA), telecom (ARCEP). Regulatory authorisation and licences held by a French company, by SIREN: payment institution, e-money institution, account-information provider, payment agent or exempt entity from the EBA PSD2 register (daily), insurance undertaking from EIOPA, telecom operator (electronic-communications operator, ARCEP). Returns authorisation dates, licensed PSD2 services, EEA passporting and withdrawals — a compliance check across three official registers. Not authorised is a paid answer too (200).','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "953990934", "denomination": "CIRCLE INTERNET FINANCIAL EUROPE SAS", "resume": {"est_agree": true, "regime": "agrement", "domaines": ["monnaie_electronique"], "nombre_agrements": 1}, "agrements": [{"domaine": "monnaie_electronique", "statut": "actif", "type_entite": "établissement de monnaie électronique", "autorite": "ACPR", "date_agrement": "2024-07-01", "date_retrait": null, "services": [{"code": "ES_010", "libelle": "Émission, distribution et remboursement de monnaie électronique"}], "passeportage": ["AT"]}], "source": "EBA (Payment Institutions Register), EIOPA (Register of Insurance Undertakings), ARCEP (opérateurs déclarés) — reproduction autorisée avec mention de la source.", "disclaimer": "Registres publics reproduits tels que publiés. Le registre EBA n''a pas de valeur juridique : l''absence d''inscription ne prouve pas l''absence d''agrément, et l''inscription ne confère aucun droit — vérifiez auprès de l''autorité compétente. Ces données sont disponibles gratuitement auprès de l''EBA, de l''EIOPA et de l''ARCEP.", "data_freshness": "eiopa-assureurs 2026-07-28, eba-pir 2026-07-28, arcep-operateurs 2026-07-28"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('ffe845ac-c5c5-5c26-b45d-146e52bee1eb','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/association/{rna}','GET',0.005,true,true,'French association (loi 1901) profile by RNA number. Official profile of a French association (loi 1901) by RNA number (W + 9), from the RNA register (Ministry of the Interior, monthly): title, purpose and Waldec codes, nature, grouping, position (active/dissolved/deleted), creation, declaration, JO publication and dissolution dates, registered office, website, RUP number as declared, prefecture, and the SIREN when Sirene confirms it (categorie juridique 92xx). Covers associations WITHOUT a SIREN. No officer data. Excludes Alsace-Moselle.','{"type": "object", "properties": {"rna": {"type": "string", "minLength": 3, "maxLength": 14, "description": "RNA number (W + 9, e.g. W751004076) or legacy RNA id as published", "x-parameter-location": "path"}}, "required": ["rna"]}'::jsonb,'{"type":"object"}','{"rna": "W751004076", "titre": "CROIX ROUGE FRANCAISE", "titre_court": "CROIX ROUGE FRANCAISE", "objet": "prévenir et alléger en toutes circonstances les souffrances humaines. Protéger la vie et la santé ainsi qu''à faire respecter la personnes humaine.", "objet_social_codes": ["017055", "050000"], "nature": {"code": "R", "libelle": "reconnue_utilite_publique"}, "groupement": {"code": "S", "libelle": "simple"}, "position": {"code": "A", "libelle": "active"}, "dates": {"creation": "1964-12-30", "derniere_declaration": "2025-09-26", "publication_jo": null, "dissolution": null}, "siege": {"adresse": "98 RUE Didot", "code_insee": "75114", "code_postal": "75694", "commune": "Paris 14e"}, "site_web": null, "publication_web_autorisee": false, "rup_mi": "75.000.0001", "prefecture_gestionnaire": "759S", "siren": "775672272", "siren_origine": "identifiant_sirene", "siret_declare": null, "fichier_source": "waldec", "fraicheur": {"qualite": "declaree", "derniere_mise_a_jour": "2026-03-28T19:00:02.000Z", "millesime_export": "2026-09-01"}, "anomalies": [], "data_freshness": "export RNA 2026-09-01 (photo mensuelle, 5 j)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('60e412ae-1123-5df3-bd20-66e72dc18d3a','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/associations/recherche','GET',0.002,true,true,'Search French associations by name (RNA, top 20). Search French associations (loi 1901) by name in the Répertoire national des associations (RNA, Ministry of the Interior): trigram similarity on the normalised title, optional postal-code, department and position filters (active, dissoute, supprimee), top 20 with score_confiance and the RNA number to use on /v1/association/{rna}. Associations with AND without a SIREN; the legacy file (no declaration since 2009) is flagged fichier_source: import. Excludes Alsace-Moselle (local law).','{"type": "object", "properties": {"q": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Association title, or an RNA number (resolved directly)", "x-parameter-location": "query"}, "code_postal": {"type": "string", "pattern": "^\\d{2,5}$", "maxLength": 500, "minLength": 1, "description": "Postal code or prefix (2-5 digits)", "x-parameter-location": "query"}, "departement": {"type": "string", "maxLength": 500, "minLength": 1, "description": "01-95, 2A, 2B or 971-989", "x-parameter-location": "query"}, "position": {"type": "string", "enum": ["active", "dissoute", "supprimee"], "maxLength": 500, "minLength": 1, "description": "Position filter", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type":"object"}','{"q": "croix rouge", "filtres": {"code_postal": "75", "departement": null, "position": null}, "total_results": 2, "resultats": [{"rna": "W751004076", "titre": "CROIX ROUGE FRANCAISE", "position": "active", "code_postal": "75694", "commune": "Paris 14e", "date_creation": "1964-12-30", "siren": "775672272", "fichier_source": "waldec", "correspondance": "debut_du_titre", "score_confiance": 0.55}], "etages_abandonnes": [], "data_freshness": "export RNA 2026-09-01 (photo mensuelle, 5 j)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('7f8b0856-a0a6-5528-860c-1e1723230584','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/association/{rna}/annonces','GET',0.01,true,true,'JOAFE notices of a French association (creations, modifications, dissolutions). Official Journal notices of a French association (JOAFE, DILA) by RNA number: creations, modifications (title, purpose, registered office), dissolutions, corrections — the association equivalent of BODACC notices, most recent first, with issue date, declaration date and prefecture, purpose themes and the PDF file name. Carries `couverture` (first and last loaded issue): no notice inside that window is a fact, not a gap. Weekly issue, loaded every Tuesday.','{"type": "object", "properties": {"rna": {"type": "string", "minLength": 3, "maxLength": 14, "description": "RNA number (W + 9, e.g. W011006690)", "x-parameter-location": "path"}}, "required": ["rna"]}'::jsonb,'{"type":"object"}','{"rna": "W011006690", "association": {"titre": "MEXIMIEUX EN MOUVEMENT", "position": "active"}, "nombre": 1, "tronque": false, "annonces": [{"identifiant": "202600350001", "parution": "20260035", "date_parution": "2026-09-01", "numero_annonce": 1, "type": {"code": "1", "libelle": "creation"}, "forme": "assoLoi1901", "departement": "01", "date_declaration": "2026-08-23", "lieu_declaration": "Belley", "titre": "MEXIMIEUX EN MOUVEMENT", "ancien_titre": null, "nouveau_titre": null, "objet": "promouvoir, organiser et développer la pratique sportive sous toutes ses formes, dans une optique multisport, à destination de tous les publics", "nouvel_objet": null, "siege": {"adresse": "8 rue du Faubourg", "code_postal": "01800", "commune": "Meximieux"}, "site_web": null, "themes": [{"code": "011005", "libelle": "associations multisports locales"}], "fichier_pdf": "JOAFE_PDF_Unitaire_20260035_00001.pdf"}], "couverture": {"depuis": "2020-01-07", "jusqu_a": "2026-09-01", "parutions": 348}, "data_freshness": "JOAFE parution 20260035 (5 j)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('dc4fdb99-fc02-551d-8e5b-56d30928832a','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/marches-publics-ue','GET',0.02,true,true,'European public-procurement awards won (TED, identifier-matched). European public procurement contract awards won by a French company, from TED (Tenders Electronic Daily, EU Publications Office): government contracts and tenders — buyer, country, subject, notice-level amount, CPV codes, co-winners and official notice link. Identifier-based matching only (SIREN/SIRET incl. spaced variants). Coverage: eForms award notices since 2023-10-25, above EU thresholds; ~57% of award notices carry a usable national identifier — an empty list is not proof of absence.','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "428634356", "nombre_avis": 1, "nombre_retourne": 1, "tronque": false, "avis": [{"reference_ted": "425760-2026", "date_publication": "2026-06-22", "type_avis": "can-standard", "objet": "Études préliminaires usines d''eau potable", "acheteur": {"nom": "SYNDICAT EAU47", "pays": "FRA"}, "montant_avis": {"valeur": 1250000, "devise": "EUR", "portee": "avis entier (tous lots/titulaires)"}, "codes_cpv": ["71241000"], "co_titulaires": ["CABINET MERLIN"], "identifiants_gagnants": ["42863435600532"], "lien_ted": "https://ted.europa.eu/fr/notice/425760-2026/pdf", "correspondance": {"methode": "identifiant", "confiance": "haute"}}], "source": "TED — Tenders Electronic Daily (ted.europa.eu), Office des publications de l''UE ; réutilisation libre, © Union européenne", "data_freshness": "interrogation TED en direct, cache 24 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('d9e0985f-9425-56c3-8d07-27d6e242dce0','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/entreprise/{siren}/lobbying','GET',0.01,true,true,'Lobbying profile from the official HATVP interest-representative register. Lobbying and influence profile of a French company from the official HATVP register of interest representatives — a transparency, governance and ESG due diligence signal: registration status, category, lobbying-expense brackets per fiscal year, staff count, recent subjects with intervention domains and action types, clients (for consulting firms), affiliations, declaration defaults and deregistrations. Organisation-level only — no personal data. Not registered is a meaningful answer (still 200).','{"type": "object", "properties": {"siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN (Luhn-validated)", "x-parameter-location": "path"}}, "required": ["siren"]}'::jsonb,'{"type":"object"}','{"siren": "552032534", "inscrit": true, "denomination": "DANONE", "categorie": {"code": "SCOMCIV", "famille": "ENTREPRISE"}, "date_premiere_publication": "2017-12-05", "desinscription": null, "exercices": [{"fin": "2025-12-31", "nb_salaries": 1, "nb_activites": 8, "depenses_tranche": "> = 200 000 euros et < 300 000 euros", "defaut_declaration": false}], "sujets_recents": [{"date": "2026-04-08", "objet": "Soutenir le développement des innovations en faveur de la transition agroécologique, de la collecte et du recyclage du plastique notamment via la consigne", "domaines": ["Agriculture, agroalimentaire"]}], "clients": [], "source": "HATVP — Répertoire des représentants d''intérêts (AGORA), Licence Ouverte 2.0", "disclaimer": "Données DÉCLARATIVES publiées par la HATVP, restituées au niveau de l''organisation (aucune personne physique) et resynchronisées régulièrement — le champ `objet` des sujets est le texte déclaré par l''organisation. Ni un avis ni une appréciation sur la licéité des activités.", "data_freshness": "répertoire HATVP (extrait 2026-07-27)"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('5e529f19-258a-5f6d-bca3-7c393523cdbc','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/regulateurs/fr/alertes','GET',0.01,true,true,'French regulator (AMF) alerts: blacklists, PSAN registrations, licensed SGP. French financial regulator alerts and scam check against the official AMF blacklist: screen a name for unauthorized investment websites, scams and AMF impersonation, and look up PSAN crypto provider registrations and licensed asset management companies (SGP) by name or SIREN. A compliance screening of the regulator blacklists for agents vetting French counterparties in crypto and asset management. Official AMF open data (Licence Ouverte 2.0), refreshed daily.','{"type": "object", "properties": {"nom": {"type": "string", "minLength": 2, "maxLength": 100, "description": "Name to screen (site, brand, company) — required unless siren is given", "x-parameter-location": "query"}, "siren": {"type": "string", "pattern": "^\\d{9}$", "maxLength": 500, "minLength": 1, "description": "9-digit SIREN for PSAN/SGP register lookup — required unless nom is given", "x-parameter-location": "query"}}, "required": ["nom"]}'::jsonb,'{"type":"object"}','{"requete": {"nom": null, "siren": "552032534"}, "correspondances_liste_noire": [], "psan": [], "sgp": [], "listes": {"liste_noire": {"disponible": true, "entrees": 3382, "rafraichie_le": "2026-07-29T07:29:17.796Z"}}, "source": "AMF — Autorité des marchés financiers, jeux open data officiels sur data.gouv.fr (listes noires, liste blanche PSAN, SGP agréées), Licence Ouverte 2.0, export quotidien", "disclaimer": "Aide au criblage par rapprochement de noms sur les listes telles que publiées par l''AMF — ni un avis de conformité ni une décision ; vérifier toute correspondance sur amf-france.org. Une liste `disponible: false` signifie que sa source est momentanément injoignable (jamais un faux « aucune correspondance »).", "data_freshness": "listes AMF quotidiennes (data.gouv), cache 24 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('05ee7c8d-43d3-5573-8550-88a27302e32e','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/eu/agrements','GET',0.01,true,true,'EU financial authorisations (ESMA Registers, all EU/EEA countries). EU financial authorisation lookup in the official ESMA Registers: search ~14,000 MiFID-regulated entities across the EU/EEA (investment firms, UCITS/AIFM managers) by name or LEI — authorisation status of the regulated entity, home and host member states, competent authority, authorisation dates. One integration covers all 27+ countries of Europe: an investment firm and regulated entity KYB check for the whole single market. Data freely available at the source (ESMA).','{"type": "object", "properties": {"q": {"type": "string", "maxLength": 500, "minLength": 1, "description": "Entity name or 20-char LEI — unsupported characters are stripped rather than rejected (1 to 100 characters once cleaned up).", "x-parameter-location": "query"}, "pays": {"type": "string", "pattern": "^[A-Za-z]{2}$", "maxLength": 500, "minLength": 1, "description": "Optional ISO-3166 alpha-2 home-member-state filter", "x-parameter-location": "query"}}, "required": ["q"]}'::jsonb,'{"type":"object"}','{"requete": {"q": "BNP Paribas", "pays": null}, "nombre_total": 64, "nombre_retourne": 10, "tronque": true, "agrements": [{"nom": "BNP PARIBAS ASSET MANAGEMENT EUROPE", "lei": "W51AX6427FJZJFPF8H34", "type_entite": "UCITS management company", "autorite_competente": "Autorité des Marchés Financiers (AMF)", "pays_origine": "FRANCE", "pays_accueil": ["AUSTRIA"], "statut": "Active", "date_autorisation": "2002-04-01T00:00:00Z", "date_retrait": null}], "source": "ESMA Registers — European Securities and Markets Authority (registers.esma.europa.eu). This data is freely available at the source.", "disclaimer": "Entités telles que publiées dans le registre unifié ESMA au moment de la consultation (statuts, autorités, passeports) — ni un avis de conformité ni une confirmation d''agrément ; vérifier auprès de l''autorité compétente.", "data_freshness": "interrogation ESMA en direct, cache 1 h"}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('671184a2-54ab-5692-bc91-d2710b220028','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/sanctions/check','GET',0.02,true,true,'Sanctions screening against the 6 official lists (UN, EU, OFAC, UK, FR, CH). Matches with 0-100 confidence score and level (forte/possible/faible), matched alias, source list, regime, birth year, plus the inventory of loaded lists — each with its entry count, publication date and `precision_publication` saying whether that date is the upstream official publication or Sirenic''s ingestion date (OFAC publishes none). Never a bare yes/no. Carries the common `provenance[]` envelope (states and reading rules: GET /v1/lecture, free).','{"type": "object", "properties": {"name": {"type": "string", "minLength": 2, "maxLength": 100, "description": "Person or company name to screen", "x-parameter-location": "query"}, "birth_year": {"type": "string", "pattern": "^\\d{4}$", "maxLength": 500, "minLength": 1, "description": "Optional birth year to refine person matches", "x-parameter-location": "query"}}, "required": ["name"]}'::jsonb,'{"type":"object"}','{"requete": {"nom": "Vladimir Putin", "annee_naissance": 1952}, "nombre_correspondances": 1, "repartition_niveaux": {"forte": 1, "possible": 0, "faible": 0}, "correspondances": [{"liste": "ue", "nom_principal": "Vladimir Vladimirovich PUTIN", "score": 93, "niveau": "forte", "regime": "(EU) 2022/330"}], "troncature": {"tronquee": false, "correspondances_servies": 1, "non_servies": 0, "niveau_non_servi": null, "prefiltre_sature": false, "note": null}, "listes_consultees": [{"liste": "ue", "libelle": "Liste consolidée des sanctions financières de l''UE (FSF)", "entrees": 6017, "publication": "2026-07-28"}], "listes_absentes": []}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('eda5ef9c-0d84-503d-9cf6-6c6f9844334e','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/iban/verifier/{iban}','GET',0.005,true,true,'IBAN form check (structure + key) and bank identification from official registries — NOT a payee verification. IBAN verification and bank validation for SEPA payments: a FORM check to verify a supplier before payment — ISO 13616 structure + mod-97 key, plus bank identification from FREE official sources (FR via ACPR/REGAFI incl. LEI and SIREN; BE NBB; AT OeNB incl. LEI; NL BIC list; DE Bundesbank file). French BICs via GLEIF/SWIFT BIC-to-LEI. NOT a payee verification for instant payments: neither the holder name nor the account''s existence is checked (verification_titulaire: non_disponible).','{"type": "object", "properties": {"iban": {"type": "string", "minLength": 15, "maxLength": 42, "description": "IBAN (spaces and dashes tolerated)", "x-parameter-location": "path"}}, "required": ["iban"]}'::jsonb,'{"type":"object"}','{"iban_normalise": "FR1420041010050500013M02606", "valide": true, "controles": {"pays_connu": "ok", "longueur": "ok", "mod97": "ok"}, "code_banque": "20041", "nature_du_controle": "forme_et_registres", "non_verifie": ["existence_du_compte", "nom_du_titulaire"], "exemple_de_documentation": true, "banque": {"identifiee": true, "nom": "La Banque Postale", "bic": "PSSTFRPPXXX", "lei": "96950066U5XAAIRCPA78", "siren": "421100645"}, "verification_titulaire": "non_disponible", "disclaimer": "Contrôle de FORME (structure ISO 13616 + clé mod 97-10) et registres publics uniquement — ceci n''est PAS une Verification of Payee au sens du règlement (UE) 2024/886 (le schéma VoP est réservé aux prestataires de services de paiement) : le nom du TITULAIRE du compte n''est jamais vérifié. L''existence du compte n''est pas contrôlée. / Format check (ISO 13616 structure + mod 97-10 check digits) and public registers only — NOT a Verification of Payee: the account holder''s name is never checked and the account''s existence is not tested."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id) VALUES('eee978bb-cd17-56c7-96cd-e848a49e7a28','804c77ce-bac1-4880-9e83-04f8b701b839','/v1/tva/verifier/{numero}','GET',0.003,true,true,'Validate an EU intra-community VAT number (VIES) before invoicing or paying. EU VAT validation against the official VIES service: validate any intra-community VAT number (all member states) for compliance and due diligence. This tax id check is the tax half of verify supplier before payment, and a required check under the e-invoicing mandate France September 2026. Returns valid/invalid/unavailable status with the VIES consultation identifier as proof — VAT number validation usable across Europe for KYB and supplier onboarding.','{"type": "object", "properties": {"numero": {"type": "string", "pattern": "^[A-Z]{2}[A-Za-z0-9+*]{2,12}$", "maxLength": 500, "minLength": 1, "description": "Full VAT number with country prefix, e.g. FR27552032534", "x-parameter-location": "path"}}, "required": ["numero"]}'::jsonb,'{"type":"object"}','{"numero": "FR27552032534", "pays": "FR", "statut": "valide", "nom": "SA DANONE", "adresse": "59 RUE LA FAYETTE 75009 PARIS", "request_identifier": null, "verifie_le": "2026-07-29T07:29:08.915Z", "valide": true, "source": "VIES — Commission européenne (service officiel de validation TVA)", "disclaimer": "Statut au moment de la consultation ; en cas d''indisponibilité du service de l''État membre, le statut est `indisponible` (jamais un faux invalide)."}'::jsonb,ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4') ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description,query_params=EXCLUDED.query_params,price=EXCLUDED.price,active=true WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.method=EXCLUDED.method AND api_endpoints.path=EXCLUDED.path;
